INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_018', 'ต้นอายุมากกว่าเต้ 10 ปี อีก 3 ปีข้างหน้า ต้นจะมีอายุเป็น 2 เท่าของเต้ ปัจจุบันต้นกับเต้มีอายุรวมกันเท่าไร', '["22 ปี", "24 ปี", "26 ปี", "36 ปี"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

18. ตอบ 2) 24 ปี
ปัจจุบัน อีก 3 ปีข้างหน้า
ต้น x + 10 (x+10) + 3
เต้ x x + 3
จาก อีก 3 ปี ต้นจะมีอายุเป็น 2 เท่าของเต้
จะได้สมการ x + 13 = 2 (x+3)
x + 13 = 2x + 6
x = 7
ดังนั้น เต้ อายุ 7 ปี และต้นอายุ (7+10) = 17 ปี
ผลรวมของอายุเต้และต้น = 7 + 17 = 24 ปี', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_019', 'ปุกมีเงินเป็น 5 เท่าของปุ๊ เมื่อคูณรวมกันได้ 125 บาท อยากทราบว่าปุ๊มีเงินเท่าไร', '["25 บาท", "35 บาท", "45 บาท", "55 บาท"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

19. ตอบ 1) 25 บาท
กำหนดให้ ปุ๊ มีเงิน x บาท
ปุก มีเงิน 5x บาท
จะได้สมการ 5x = 125
ดังนั้น x = 25 → ปุ๊มีเงิน 25 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_020', 'พนักงานขายจะได้รับค่าคอมมิชชั่นจากการขายสินค้าประเภทเครื่องประดับ 10% และประเภทอื่นๆ 7% เมื่อลูกค้าซื้อเครื่องประดับ 20,000 บาท เสื้อผ้า 3,200 บาท และต่างหู 17,000 บาท พนักงานจะได้รับค่าคอมมิชชั่นทั้งหมดกี่บาท', '["4,290 บาท", "3,414 บาท", "3,924 บาท", "4,020 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

20. ตอบ 3) 3,924 บาท
เครื่องประดับ ; 20,000 × 10/100 = 2,000
เสื้อผ้า ; 3,200 × 7/100 = 224
ต่างหู ; 17,000 × 10/100 = 1,700 (ต่างหูจัดอยู่ในประเภทเครื่องประดับ)
คอมมิชชั่นรวม = 2,000 + 224 + 1,700 = 3,924 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_021', 'ที่ดินทั้งหมด 50 ไร่ เลี้ยงปลา 30% ของพื้นที่ทั้งหมด ปลูกต้นไม้ 60% ของพื้นที่ทั้งหมด ปลูกมังคุด 60% ของพื้นที่ปลูกผลไม้ ปลูกลองกอง 50% ของพื้นที่ปลูกมังคุด จะเหลือพื้นที่ปลูกต้นไม้สำหรับปลูกลำไยได้กี่ไร่', '["3 ไร่", "6 ไร่", "9 ไร่", "12 ไร่"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

21. ตอบ 1) 3 ไร่
เลี้ยงปลา 30% =   30/100 × 50 = 15 ไร่
ปลูกผลไม้ 60% =   60/100 × 50 = 30 ไร่
ปลูกมังคุด 60% ของพื้นที่ปลูกผลไม้ =   60/100 × 30 = 18 ไร่
ปลูกลองกอง 50% ของพื้นที่ปลูกมังคุด =   50/100 × 18 = 9 ไร่
ดังนั้น เหลือพื้นที่ปลูกลำไย = 30 – 18 – 9 = 3 ไร่', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_022', 'ถนนเส้นหนึ่งยาว 88.5 กิโลเมตร ฝั่งซ้ายปลูกต้นมะขามห่างกันต้นละ 750 เมตร ฝั่งขวาห่างกันต้นละ 500 เมตร ถนนเส้นนี้มีต้นมะขามทั้งหมดกี่ต้น', '["297 ต้น", "277 ต้น", "312 ต้น", "327 ต้น"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

22. ตอบ 297 ต้น
ระยะทาง 88.5 กิโลเมตร เท่ากับ 88,500 เมตร
ซ้าย ;   88,500/750 = 118 + 1 = 119 [+1 จากต้นแรกที่ระยะ 0 เมตร]
ขวา ;   88,500/500 = 177 +1 = 178 [+1 จากต้นแรกที่ระยะ 0 เมตร]
ดังนั้นถนนสายนี้มีต้นมะขามทั้งหมด 119 + 178 = 297 ต้น', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'Paper', 0);
