INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_074', 'ข้อใดคือสาระสำคัญของบทความต่อไปนี้
