2. I would like to drink something first. ฉันต้องการเครื่องดื่มสักอย่าง
3. I would like fried noodles and spicy soup. ฉันต้องการเส้นผัดกับซุปเผ็ด (สอดคล้องกับโจทย์ที่
พูดว่า Is the spicy soup good การใช้ ‘the’ คือการกล่าวถึงสิ่งที่พูดไปก่อนหน้า)
4. I think I’ll have salad and onion soup. ฉันคิดว่าฉันจะกินสลัดกับซุปหัวหอม', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["บทสนทนา"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_084', 'จงอ่านบทสนทนาต่อไปนี้และตอบคำถามข้อ 6 - 10
Waiter : Hello, . . . (6) . . .
Customer : Yes, I would like to have some lunch.
Waiter : Great, would you like to order now ?
Customer : Yes, . . . (7) . . .. Is the spicy soup good ?
Waiter : Yes, it’s very good !, . . .(8) . . . ?
Customer : Yes, a coke please.
Waiter : . . . (9) . . . I can do for you ?
Customer : Yes, I would like a dessert please. . . . . (10). . . ?
Waiter : Caramelized bananas with coconut milk ice cream.
Customer : Okay, I will have that.

