INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_091', 'What is another word for ‘give up’ ?', '["quit", "consist", "emotion", "custom"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

15. ตอบ1) quit
give up หมายถึง ยอมแพ้
1. quit เลิก/หยุด/ละทิ้ง 2. consist ประกอบด้วย
3. emotion อารมณ์ 4. custom กำหนดเอง', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Vocabulary"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_092', 'What is another word for ‘expiration’ ?', '["ending", "starting", "expected", "best before"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

16. ตอบ1) ending
expiration หมายถึง หมดอายุ, สิ้นสุด
1. ending จบ
2. starting การเริ่ม
3.expected ความคาดหวัง
4. best before ดีที่สุดก่อน… (มักตามด้วยวันที่ ใช้กับวันหมดอายุของอาหาร หมายถึงการใช้ก่อนวันนั้นๆ
โดยหลังจากนั้นสามารถบริโภคได้แต่อาจมีคุณลักษณะไม่พึงประสงค์เกิดขึ้นได้)', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Vocabulary"]', '2565', 'Paper', 0);
