คำแปล : ปริมาณของฝุ่นละอองขนาด 2.5 อยู่ใน ‘ระดับ’ อันตรายในกรุงเทพฯ
1. rank อันดับ 2. floors ชั้น 3. levels ระดับ 4. methods วิธี', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Reading"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_094', 'What is another word for ‘increase’ ?', '["add", "change", "return", "suggest"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

18. ตอบ 1) add
increase หมายถึง เพิ่ม
1. add เพิ่ม 2. change เปลี่ยน 3. return กลับ 4. suggest แนะนำ', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Vocabulary"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_095', 'You can find a coffee shop .... the office building and the movie theater.', '["among", "between", "through", "surrounding"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

19. ตอบ 2) between
You can find a coffee shop . . . the office building and the movie theater.
คำแปล : คุณสามารถหาร้านกาแฟได้ระหว่างตึกออฟฟิศและโรงหนัง
Keyword = “and” จึงตอบ between
1. among ท่ามกลาง (ใช้กับ 3 สิ่งขึ้นไป)
2. between ระหว่าง ใช้เชื่อม 2 สิ่งเข้าด้วยกัน มักมีคำว่า and เชื่อมระหว่างคำ 2 คำ
3. through ผ่าน , ทะลุ
4. surrounding รอบๆ', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_096', 'After a long time argument, most executives insist on giving .... a pay raise.', '["himself", "ourselves", "yourself", "themselves"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

20. ตอบ 4) themselves
After a long time argument, most executives insist on giving ....... a pay raise.
คำแปล : หลังจากการถกเถียงกันเป็นเวลานาน, ผู้บริหารส่วนใหญ่ยืนยันที่จะให้พวกเขาได้ขึ้นเงินเดือน
executives = มีประธานหลายคน
1. himself ใช้กับ He 2. ourselves ใช้กับ We
3. yourself ใช้กับ You 4. themselves ใช้กับ They', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_097', '[ปวส] How .... time have we got ?', '["much", "many", "some", "long"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

21. ตอบ 1) much
How . . . time have we got ?
คำแปล : เรามีเวลาเท่าไร
ถามเวลา ตอบ much เพราะเป็นนามนับไม่ได้', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_098', '[ปวส] It’s very ....', '["interest", "interested", "interesting", "interester"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

22. ตอบ 3) interesting
It’s very . . ..
คำแปล : มันน่าสนใจมาก
1. interest สนใจ 2. interested รู้สึกสนใจ
3. interesting น่าสนใจ 4. interester', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_099', 'The meat .... by a dog.', '["is eat", "was eat", "was ate", "was eaten"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

23. ตอบ 4) was eaten
The meat . . . by a dog.
คำแปล : เนื้อถูกกินโดยสุนัข
สังเกตว่าเป็น Passive voice ในรูป past เพราะเนื้อถูกสุนัขกินไปแล้ว
จะได้โครงสร้างเป็น S + was/were + v.3', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_100', 'I wash my face and .... my teeth every morning.', '["brush", "brusher", "brushed", "brushing"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

24. ตอบ 1) brush
I wash my face and . . . my teeth every morning.
คำแปล : ฉันล้างหน้าและแปรงฟันทุกเช้า
เป็น present simple เพราะเล่าถึงเหตุการณ์ปัจจุบัน โครงสร้าง S + v.1', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_101', 'The teacher advised the students .... all references they used.', '["give", "giving", "to give", "to given"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

25. ตอบ 3) to give
The teacher advised the students . . . all references they used.
คำแปล : ครูแนะนำนักเรียน . . . แหล่งอ้างอิงทั้งหมดที่พวกเขาใช้
advise someone + to + v.infinitive', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_102', 'The meeting will be .... on Monday. Don’t forget to mark your calendar.', '["held", "built", "produced", "worked"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

26. ตอบ 1) held
The meeting will be . . . on Monday. Don’t forget to mark your calendar.
คำแปล : งานมีทติ้งที่จะ. . . ในวันจันทร์ อย่าลืมลงปฏิทินของเธอไว้ด้วยนะ
1. held เป็น v.3 ของ hold แปลว่าถือ/จัดงาน 2. built สร้าง (ใช้กับสิ่งก่อสร้าง)
3. produced ผลิต 4. worked ทำงาน', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_103', 'Illnesses and deaths .... to lung disease have occurred both in young people and older adults.', '["related", "respected", "reviewed", "represented"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

27. ตอบ 1) related
Illnesses and deaths . . . to lung disease have occurred both in young people and older adults.
คำแปล : ความตายและการเจ็บป่วยที่…กับโรคปอด มักเกิดขึ้นบ่อยครั้งในวัยหนุ่มสาวและวัยผู้ใหญ่
สังเกตคำว่า to เลือกตอบเป็น related เพราะมักมากับคำว่า to เป็น v.infinitive
1. related เกี่ยวข้อง 2. respected เคารพ
3. reviewed ทบทวน 4. represented เป็นตัวแทน', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_104', 'Our planet’s wildlife is in crisis as the wildlife species are becoming extinct at a/an .... rate.', '["average", "alarming", "expected", "competitive"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

28. ตอบ 2) alarming
Our planet’s wildlife is in crisis as the wildlife species are becoming extinct at a/an . . rate.
คำแปล : สัตว์โลกกำลังวิกฤต เพราะสายพันธุ์กำลังจะสูญพันธุ์ในอัตราที่ . . .
1. average ทั่วไป 2. alarming น่าตกใจ
3. expected ที่คาดการณ์ไวแล้ว 4. competitive การแข่งขัน', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_Paper_105', 'Runners must drink a lot of water so that they do not get ....', '["delayed", "deleted", "determined", "dehydrated"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

