INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_027', '2 * 3 = 125
6 * 2 = 512
2 * 2 = ?', '["25", "64", "81", "121"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

27. ตอบ 2) 64
จากความสัมพันธ์ (หน้า + หลัง)^3  = ผลลัพธ์
จะได้ (2 + 3)^3  = 5^3  = 125
(6 + 2)^3  = 8^3  = 512
ดังนั้น (2 + 2)^3  = 4^3  = 64', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป", "โอเปอเรชัน"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_028', '5 * 8 = 9
2 * 4 = 4
4 * 2 = ?', '["-2", "2", "-4", "4"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

28. ตอบ 4) 4
จากความสัมพันธ์ (หน้า – หลัง)^2  = ผลลัพธ์ หรือ (หลัง – หน้า)^2 = ผลลัพธ์
จะได้ (5 - 8)^2  = (-3)^2 = 9
(2 - 4)^2  = 2^2  = 4
ดังนั้น (4 - 2)^2  = 2^2  = 4', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป", "โอเปอเรชัน"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_029', '4 * 2 = 20
5 * 7 = -20
8 * 9 = ?', '["10", "-10", "20", "-20"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

29. ตอบ 2) -10
จากความสัมพันธ์ (หน้า – หลัง) × 10 = ผลลัพธ์
จะได้ (4 - 2) × 10 = 2 × 10 = 20
(5 - 7) × 10 = (-2) × 10 = -20
ดังนั้น (8 - 9) × 10 = (-1) × 10 = -10', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป", "โอเปอเรชัน"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_030', '7 * 5 = 24
8 * 6 = 28
10 * 8 = ?', '["30", "32", "34", "36"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

30. ตอบ 4) 36
จากความสัมพันธ์ (หน้า)^2 – (หลัง)^2  = ผลลัพธ์
จะได้ 7^2 - 5^2  = 49 -25 = 24
8^2 – 6^2  = 64 – 36 = 28
ดังนั้น 10^2 - 8^2  = 100 – 64 = 36', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป", "โอเปอเรชัน"]', '2565', 'e-Exam1', 0);
