INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_032', 'ซื้อหน้ากากอนามัย 1 กล่อง ราคา 65 บาท ต่อมาเมื่อมีการระบาดของโควิด-19 ทำให้ราคาหน้ากากมอนามัยพุ่งสูงขึ้น จึงขายต่อในราคากล่องละ 650 บาท ต้องการทราบว่าคนขายได้กำไรกี่เปอร์เซ็นต์', '["10%", "90%", "100%", "900%"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

32. ตอบ 4) 900%
วิธีคิด กำไร 650 – 65 = 585 บาท
จะได้ 585/65 × 100 = 900%', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_033', 'สุนัข ไก่ เป็ด นก นับขารวมกันได้ 400 ขา ถ้าสัตว์ทั้ง 4 ชนิดมีจำนวนเท่ากัน สุนัขจะมีจำนวนกี่ตัว', '["36 ตัว", "40 ตัว", "44 ตัว", "48 ตัว"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

33. ตอบ 40 ตัว
วิธีคิด กำหนดให้ สุนัขมี 4 ขา, ไก่มี 2 ขา, เป็นมี 2 ขา, นกมี 2 ขา
จำนวนขาทั้งหมด
จำนวนสัตว์แต่ละชนิด =
จำนวนขาของสัตว์แต่ละชนิดจำนวน 1 ตัว
=   400/(4+2+2+7)
=   400/10 = 40 ตัว', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_034', 'แม่ค้าทำขนม 80 ชิ้น โดยแบ่งใส่กล่อง แต่ละกล่องใส่ขนม 1/16 ชิ้นของขนมทั้งหมด นำไปขายกล่องละ 35 บาท เมื่อขายขนมหมดแม่ค้าจะได้เงินกี่บาท', '["540 บาท", "575 บาท", "560 บาท", "590 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

34. ตอบ 560 บาท
วิธีคิด แต่ละกล่องใส่ขนม 1/16 × 80 = 5 ชิ้น
มีขนมทั้งหมด   80/5 = 16 กล่อง
ดังนั้น จะได้เงินทั้งหมด = 16 × 35 = 560 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_035', 'คน 5 คน มีน้ำหนักเฉลี่ย 30 กิโลกรัม มี 1 คนออกไป ซึ่งมีน้ำหนัก 50 กิโลกรัม คนที่เหลือ 4 คน จะมีน้ำหนักเฉลี่ยเท่าไร', '["25", "26", "27", "28"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

35. ตอบ 1) 25
วิธีคิด จาก ค่าเฉลี่ย = น้าหนักรวมทุกคน/จานวนคน จากโจทย์จะได้ว่า 30 = น้าหนักรวม5คน/5
น้ำหนักรวม 5 คน = 150 กิโลกรัม
มี 1 คนออกไป น้ำหนักรวมเหลือ =150 – 50 = 100 กิโลกรัม
ดังนั้น ค่าเฉลี่ยน้ำหนัก 4 คน = 100/4 = 25 กิโลกรัม', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_036', 'นพพรมีเงินเดือน 16,500 บาท ปัจจุบันฝากธนาคาร 3,000 บาทต่อเดือน หากต้องการฝากให้ได้ 30% ของเงินเดือนจะต้องเพิ่มเงินฝากอีกกี่บาท', '["900 บาท", "1,800 บาท", "1,950 บาท", "4,950 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

36. ตอบ 3) 1,950 บาท
วิธีคิด 30% ของเงินเดือน = 30/100 × 16,500 = 4,950 บาท
ดังนั้น ต้องฝากเพิ่มอีก 4,950 – 3,000 = 1,950 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_037', 'พ่อแบ่งเงินให้ลูกทั้งหมด 35,835 บาท โดยแบ่งให้ลูก 3 คน คนโตได้ 8 เท่าของคนเล็ก คนกลางได้ 75% ของคนโต ต้องการทราบว่าคนเล็กน้อยเงินน้อยกว่าคนกลางกี่บาท', '["5,725 บาท", "9,650 บาท", "11,945 บาท", "15,463 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

37. ตอบ 3) 11,945 บาท
วิธีคิด กำหนดให้ ลูกคนเล็ก ได้เงิน x บาท
ลูกคนโต ได้เงิน 8x บาท
ลูกคนกลาง ได้เงิน 75/100 (8x) = 6x บาท
จะได้สมการ 8x + 6x + x = 35,835
15x = 35,835
x = 2,389
ดังนั้น คนกลาง – คนเล็ก = 6x – x
= 5x
= 5 (2,389) = 11,945 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_038', 'ถังน้ำใบหนึ่งมีน้ำรั่วออกไป 1/6 ของถัง ต่อมาตักออก 6 ลิตร ปรากฏว่าน้ำเหลือครึ่งถังพอดี เดิมถังนี้บรรจุน้ำได้ทั้งหมดกี่ลิตร', '["15 ลิตร", "18 ลิตร", "21 ลิตร", "24 ลิตร"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

38. ตอบ 2) 18 ลิตร
วิธีคิด กำหนดให้ ถังบรรจุน้ำได้ x ลิตร
น้ำรั่วออกไป   (1/6)x ลิตร
ตักออก 6 ลิตร น้ำเหลือ (1/2)x ลิตร
จะได้สมการ x - (1/6)x – 6 =   (1/2)x → คูณ 6 ทั้งสมการ
จะได้ 6x – x – 36 = 3x
5x – 36 = 3x
2x = 36
x = 18', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_039', 'มีน้ำในถัง 1/3 ของถัง เติมน้ำลงไป 1,500 ลิตร ทำให้มีน้ำเป็น 3/4 ของถัง อยากทราบว่าถังใบนี้บรรจุน้ำได้ทั้งหมดกี่ลิตร', '["3,600 ลิตร", "3,500 ลิตร", "3,700 ลิตร", "3,800 ลิตร"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

39. ตอบ 3,600 ลิตร
วิธีคิด กำหนดให้ ถังบรรจุน้ำได้ x ลิตร
เติมน้ำ = น้ำที่มีหลังเติม – น้ำที่มีก่อนเติม
จะได้สมการ 1,500 =   (3/4)x - (1/3)x
1,500 = 9x/12 - 4x/12
1,500 = 5x/12
x = 1,500(12)/5 = 3,600 ลิตร', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_040', 'แม่ค้ามีผลไม้ทั้งหมด 540 กิโลกรัม ขายได้วันละ 1/3 ของที่เหลือในแต่ละวัน อยากทราบว่า 3 วันแรก แม่ค้าขายผลไม้ไปทั้งหมดกี่กิโลกรัม', '["360 กิโลกรัม", "395 กิโลกรัม", "410 กิโลกรัม", "380 กิโลกรัม"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

40. ตอบ 380 กิโลกรัม
วิธีคิด วันที่ 1 ; ขายไป 1/3 × 540 = 180 กิโลกรัม
เหลือผลไม้ 540 – 180 = 360 กิโลกรัม
วันที่ 2 ; ขายไป 1/3 × 360 = 120 กิโลกรัม
เหลือผลไม้ 360 – 120 = 240 กิโลกรัม
วันที่ 3 ; ขายไป 1/3 × 240 = 80 กิโลกรัม
เหลือผลไม้ 240 – 80 = 240 กิโลกรัม
ดังนั้น 3 วันแรก ขายผลไม้ไปทั้งหมด = 180 + 120 +80 = 380 กิโลกรัม', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_041', 'พ่อมีเงินเป็น 2 เท่าของแม่ พ่อแบ่งเงินให้ลูก 2 คน คนละ 55 บาท ทำให้พ่อเหลือเงิน 46 บาท ต้องการทราบว่าแม่มีเงินกี่บาท', '["78 บาท", "70 บาท", "84 บาท", "90 บาท"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

41. ตอบ 78 บาท
วิธีคิด พ่อมีเงิน x บาท
พ่อแบ่งให้ลูก 2 × 55 = 110 บาท
จะได้สมการ x – 110 = 46
x = 156
ดังนั้น พ่อมีเงิน 156 บาท และ แม่มีเงิน 156/2 = 78 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_042', 'นาย ก ซื้อจักรยานมาในราคา 22,500 บาท ขายให้นาย ข ขาดทุน 2,250 บาท ต่อมานาย ข ขายให้นาย ค โดยได้กำไร 4% ต้องการทราบว่านาย ข ได้กำไรจากการขายจักรยานกี่บาท', '["810 บาท", "790 บาท", "825 บาท", "840 บาท"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

42. ตอบ 810 บาท
วิธีคิด นาย ข ซื้อจักรยานมาในราคา 22,500 – 2,250 = 20,250 บาท
จะได้ว่า นาย ข มีต้นทุน 20,250 บาท
ขายต่อให้นาย ค โดยได้กา ไร 4% เท่ากับ 4/100 × 20,250 = 810 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_043', 'A, B และ C มีเงินรวมกันเท่ากับ 2,016 บาท นาย A มีเงินเป็น 5 เท่าของนาย B และนาย C มีเงินเป็น 2 เท่าของนาย A ต้องการทราบว่านาย C มีเงินกี่บาท', '["1,260 บาท", "1,160 บาท", "1,360 บาท", "1,460 บาท"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

43. ตอบ 1,260 บาท
วิธีคิด กำหนดให้ นาย B มีเงิน B บาท
นาย A มีเงิน 5B บาท
นาย C มีเงิน 2(5B) = 10B บาท
จะได้สมการ 5B + B + 10B = 2,016
16B = 2,016
B = 126 บาท
ดังนั้น นาย C มีเงินเท่ากับ 10B = 10 (126)
= 1,260 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_044', 'กำหนดให้ a, b, c เป็นจำนวนจริงใดๆ แล้ว a < b < c ข้อใดถูกต้อง', '["ab < bc", "ac < bc", "a/b < c/b", "(a+b) < (b+c)"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

44. ตอบ 4) (a+b) < (b+c)
วิธีคิด กำหนดให้ a = -4, b = -2, c = -1
1. ab < bc → (-4)(-2) < (-2)(-1) → 8 < 2 เท็จ
2. ac < bc → (-4)(-1) < (-2)(-1) → 4 < 2 เท็จ
3. a/b < c/b → (-4)/(-2) < (-1)/(-2) → 2 < 1/2 เท็จ
4. (a+b) < (b+c) → [(-4)+(-2)] < [(-2)+(-1)] → -6 < -3 จริง', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_045', 'นาย A ซื้อของมาขายให้นาย B ได้กำไร 8% ต่อมานาย B ขายต่อให้นาย C เป็นเงิน 22,680 บาท ซึ่งได้กำไร 12% ต้องการทราบว่านาย A ซื้อของมาในราคากี่บาท', '["18,750 บาท", "19,250 บาท", "20,250 บาท", "22,750"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

45. ตอบ 1) 18,750 บาท
วิธีคิด หาราคาของได้จาก ทุน × 108/100 × 112/100 = 22,680
ทุน =   22,680×100×100/108×112
ทุน = 18,750 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_046', 'โรงเรียนแห่งหนึ่งมีนักเรียนใส่เสื้อทั้งหมด 3 สี โดย 1/2 ใส่เสื้อสีเหลือง 1/3 ใส่เสื้อสีแดง และ 1/6 ใส่เสื้อสีน้ำเงิน นักเรียนที่ใส่เสื้อสีเหลืองรวมกับสีแดงมีจำนวนมากกว่านักเรียนที่ใส่เสื้อสีน้ำเงิน 40 คน โรงเรียนแห่งนี้มีนักเรียนทั้งหมดกี่คน', '["50 คน", "55 คน", "60 คน", "65 คน"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

46. ตอบ 3) 60 คน
วิธีคิด กำหนดให้ มีนักเรียนทั้งหมด x คน
ใส่เสื้อสีเหลือง   (1/2)x คน
ใส่เสื้อสีแดง   (1/3)x คน
ใส่เสื้อสีน้ำเงิน   (1/6)x คน
จะได้สมการ   (1/2)x + (1/3)x + 40 =   (1/6)x
40 =   (1/6)x - (1/2)x - (1/3)x
40 =   (1/6)x - (3/6)x - (2/6)x
40 = - (4/6)x
4x = - 240
x = - 60', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_047', 'มีธนบัตรใบละ 20 บาทและใบละ 50 บาท รวมกัน 35 ใบ คิดเป็นเงินรวม 1,300 บาท อยากทราบว่าในทั้งหมดนี้มีธนบัตรใบละ 20 บาทกี่ใบ', '["11 ใบ", "19 ใบ", "15 ใบ", "23 ใบ"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

47. ตอบ 15 ใบ
วิธีคิด กำหนดให้ ธนบัตรใบละ 20 บาท มี x ใบ
ธนบัตรใบละ 50 บาท มี y ใบ
จะได้สมการ x + y = 35 - - - - - (1)
20x + 50y = 1,300 - - - - - (2)
(1) × 20 ; 20x + 20y = 700 - - - - - (3)
(2) – (3) ; 20x + 50y – 20x – 20y = 1,300 – 700
30y = 600
y = 20
แทน y = 20 ใน (1) จะได้ x + 20 = 35
x = 35 – 20 = 15
ดังนั้น ธนบัตรใบละ 20 บาท มี 15 ใบ', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_048', 'ถ้า x, y เป็นจำนวนจริงที่ x > y และ xy < 0 ข้อใดกล่าวถูกต้อง', '["xy > x", "x+y > 0", "x-y > 0", "x^2 y > 0"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

48. ตอบ 3) x-y > 0
วิธีคิด จาก 0 > xy → มีจำนวนใดจำนวนหนึ่งมีค่า – จึงคูณกันได้น้อยกว่า 0
จาก X > y → จึงกำหนดให้ x เป็นจำนวนเต็มบวก และ y เป็นจำนวนเต็มลบ
โดยทดลองแทน x = 2 และ y = -3 ในตัวเลือก ได้ดังนี้
1. xy > x → 2(-3) > 2 → -6 > 2 เท็จ
2. x + y > 0 → 2+(-3) > 0 → -1 > 0 เท็จ
3. x – y > 0 → 2-(-3) > 0 → 5 > 0 จริง
4. x^2 y > 0 → 2^2(-3) > 0 → -12 > 0 เท็จ', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_049', 'รถไฟ 2 ขบวนวิ่งสวนทางกันท่าสถานีแห่งหนึ่ง ขบวนแรกวิ่งด้วยความเร็ว 55 กิโลเมตรต่อชั่วโมง ขบวนที่สองวิ่งด้วยความเร็ว 65 กิโลเมตรต่อชั่วโมง จะต้องใช้เวลากี่ชั่วโมงรถไฟทั้งสองชบวนจึงจะอยู่ห่างกัน 480 กิโลเมตร', '["4 ชั่วโมง", "8 ชั่วโมง", "12 ชั่วโมง", "16 ชั่วโมง"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

49. ตอบ 1) 4 ชั่วโมง
วิธีคิด จาก v = s/t จะได้ว่า t = s/v
แทนในสมการ ได้ดังนี้ t = 480/(55+65) [อนุมานว่ารถไฟทั้งสองขบวนมีความเร็วรวมกัน]
t = 480/120 = 4 ดังนั้น ใช้เวลาทั้งหมด 4 ชั่วโมง', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_050', 'พนักงานเก็บขยะทำงาน 16 วัน เก็บขยะได้ร้อยละ 50 ถ้าต้องการเก็บขยะให้เหลือร้อยละ 25 ของปริมาณขยะตั้งต้น จะต้องใช้ระยะเวลากี่วัน', '["24 วัน", "20 วัน", "28 วัน", "32 วัน"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

50. ตอบ 24 วัน
