INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_082', 'ข้อความใดอยู่ลำดับที่ 1', '["กาแฟออกฤทธิ์หลังดื่ม 15 นาที", "การดื่มกาแฟเพื่อผ่อนคลาย ควรดื่มทีละน้อยๆ", "การดื่มกาแฟทีละน้อยๆมีประโยชน์กว่าการดื่มทีละมากๆ", "เราควรแบ่งดื่มกาแฟ เพื่อให้สามารถดื่มได้เรื่อยๆ"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

