เรียงลำดับได้ดังนี้ 2 - 3 - 4 – 1 คือ การดื่มกาแฟเพื่อผ่อนคลาย ควรดื่มทีละน้อยๆ การดื่มกาแฟทีละ
น้อยๆมีประโยชน์กว่าการดื่มทีละมากๆ เราควรแบ่งดื่มกาแฟ เพื่อให้สามารถดื่มได้เรื่อยๆ กาแฟออกฤทธิ์หลังดื่ม
15 นาที', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "เรียงประโยค"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_083', 'Our company is trying to .... more women to executive positions.', '["appoints", "appoint", "appointed", "appointing"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

1. ตอบ 2) appoint
