ตามหลัง to ต้องเป็น V.1', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_084', 'China is .... biggest food producer.', '["world", "the world", "world’s", "the world’s"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

2. ตอบ 4) the world’s
