INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_085', 'He has present .... grandma XXXXX ?', '["has he", "has he isn’t", "hasn’t", "hasn’t he"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

3. ตอบ 4) hasn’t he
