คำแปล : ปัจจุบันเขาไม่มีคุณย่าเขา XXXXX?', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_086', 'I visited a town .... I was raised as a child.', '["that", "which", "in that", "in which"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

4. ตอบ 4) in which
I visited a town . . . . I was raised as a child.
คำแปล : ฉันไปเที่ยวเมืองที่ฉันเคยอาศัยอยู่ตอนเป็นเด็ก
in which = where กล่าวถึงสถานที่', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_087', 'Eating too much makes the shirt ....', '["tight", "loose", "tatter", "shrivel"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

5. ตอบ 1) tight
Eating too much makes the shirt . . . .
คำแปล : การกินเยอะทำให้เสื้อ . . . .
1. tight แน่น 2. soose หลวม 3. tatter ขาดรุ่งริ่ง 4. shrivel เหี่ยว', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_088', 'A : I little lost. Can you help me ?
B : Yes, Where ....
A : I would like to go to National Museum.', '["are you from ?", "is the National Museum ?", "would you like to go ?", "do you live ?"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

6. ตอบ 3) would you like to go ?
A I little lost. Can you help me ? ฉันหลงทางเล็กน้อย คุณพอจะช่วยฉันได้ไหม
B Yes, Where . . . . ได้สิ, ที่ไหน . . . .
A I would like to go to National Museum. ฉันจะไปที่พิพิธภัณฑ์แห่งชาติ
1. are you from? คุณมาจากไหน
2. is the National Museum? พิพิธภัณฑ์แห่งชาติอยู่ที่ไหน
3. would you like to go? คุณต้องการไปที่ไหน
4. do you live? คุณอาศัยอยู่ที่ไหน', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["บทสนทนา"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_089', 'The president, accompanied by bodyguards, .... traveling in Monaco this evening.', '["is", "was", "were", "are"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

7. ตอบ 1) is
The president, accompanied by bodyguards, . . . . traveling in Monaco this evening.
คำแปล : ประธานาธิบดีพร้อมด้วยบอดี้การ์ด เดินทางมาเที่ยวที่โมนาโกเย็นวันนี้
ใช้ v.to be + v.ing บ่งบอกถึงเหตุการณ์ที่จะเกิดขึ้นตอนเย็นวันนี้
ในที่นี้ใช้ v. to be เป็น is กับประธานของประโยค คือ ประธานาธิบดี', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_090', 'A : .... does it take to fly from Bangkok to Chiang Mai ?
B : About 1 hour.', '["How far", "How long", "How often", "How much"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

8. ตอบ 2) How long
A . . . . does it take to fly from Bangkok to Chiang Mai . . . . บินจากกรุงเทพไปเชียงใหม่
?
B About 1 hour. ประมาณ 1 ชั่วโมง
1. How far ถามระยะทาง 2. How long ถามระยะเวลา
3. How often ถามความถี่หรือความบ่อย 4. How much ถามราคา', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["บทสนทนา"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_091', 'Our neighbor, .... sister lives in Hong Kong, is visiting her sister.', '["who", "whom", "whose", "where"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

9. ตอบ 3) whose
