ใช้ whose กล่าวถึงเพื่อนบ้าน และต้องใช้ whose + คำนาม เสมอ', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_092', 'Plant can’t ...., it planted indoor.', '["accrete", "extend", "exist", "resist"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

10. ตอบ 3) exist
