INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam1_093', 'I dislike .... Mavels.', '["poet", "article", "novels", "legends"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam1

