INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_024', 'หมู่บ้านแห่งหนึ่งมี 650 ครัวเรือน โดยเฉลี่ยครัวเรือนละ 4 คน มี 12% ของทั้งหมดทำอาชีพประมง และ 25% ของจำนวนที่เหลือเป็นพนักงานโรงงาน อยากทราบว่าคนทำอาชีพประมงน้อยกว่าพนักงานโรงงานกี่คน', '["200 คน", "220 คน", "240 คน", "260 คน"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

24. ตอบ 4) 260 คน
กำหนดให้หมู่บ้านนี้มีประชากร = 650 × 4
= 2,600 คน
ทำอาชีพประมง = 12/100 × 2,600 = 312 คน
เหลือ = 2,600 – 312 = 2,288 คน
ทำอาชีพพนักงานโรงงาน = 25/100 × 2,288 = 572 คน
ผลต่าง = 572 – 312 = 260 คน', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_025', '3/4 เท่าของจำนวนหนึ่งบวก 3 มีค่าเท่ากับ 45 จำนวนดังกล่าวมีค่าเท่าไร', '["42", "56", "57", "64"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

25. ตอบ 2) 56
กำหนดให้จำนวนดังกล่าว เท่ากับ X
จะได้   (3/4)X + 3 = 45
(3/4)X = 42
3X = 168
X =   169/3 = 56', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_026', 'วัชรานนท์มีเงินจำนวน 83,000 บาท นพพรมีเงิน 2/6 เท่าของสุธร และสุธรมีเงินเป็น 6/8 เท่าของวัชรานนท์ ต้องการทราบว่านพพรมีเงินอยู่กี่บาท', '["20,750 บาท", "27,500 บาท", "38,906 บาท", "62,250 บาท"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

26. ตอบ 1) 20,750 บาท
จาก สุธรมีเงิน = 6/8 × 83,000 = 62,250 บาท
นพพร มีเงิน = 2/6 × 62,250 = 20,750 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_027', '4 คูณกับ x ลบ 12 ได้ผลลัพธ์เป็นจำนวนที่หนึ่ง และ 12 ลบ x คูณด้วย 4 ได้ผลลัพธ์เป็นจำนวนที่สอง กำหนดให้จำนวนที่หนึ่งมีค่าเป็น 2 เท่าของจำนวนที่สอง จงหาค่า x', '["8", "12", "16", "20"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

27. ตอบ 12
จากโจทย์ กำหนดให้ จำนวนที่หนึ่ง = y, จำนวนที่สอง = z
จะได้สมการ 4(x-12) = y → 4x – 48 = y
4(12-x) = z → 48 – 4x = z
และ y = 2z
จะได้ 4x – 48 = 2(48-4x)
2x-24 = 48 – 4x
6x = 72
x = 12', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_028', 'เมื่อ 10 ปีที่แล้ว แดงมีอายุเป็น 3 เท่าของดำ อีก 10 ปีข้างหน้า แดงจะมีอายุเป็น 2 เท่าของดำ ปัจจุบันดำและแดงมีอายุเท่าไร', '["ดำอายุ 25 ปี, แดงอายุ 65 ปี", "ดำอายุ 28 ปี, แดงอายุ 68 ปี", "ดำอายุ 32 ปี, แดงอายุ 72 ปี", "ดำอายุ 30 ปี, แดงอายุ 70 ปี"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

28. ตอบ ดำอายุ 30 ปี, แดงอายุ 70 ปี
เวลา แดง ดำ
10 ปีที่แล้ว 3x x
ปัจจุบัน 3x + 10 x + 10
10 ปีข้างหน้า 3x + 20 x + 20
หรือ 2(x+20) จาก 2 เท่าของดำ
จะได้สมการ 3x + 20 = 2(x + 20)
3x + 20 = 2x + 40
x = 20
ดังนั้น ปัจจุบัน แดง ; 3x + 10 = 3(20) + 10 = 70 ปี
ดา ; x + 10 = 20 + 10 = 30 ปี', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_029', 'โรงเรียนแห่งหนึ่งมีการสอบไล่ระดับชั้น มีผู้สอบผ่าน 70% ซึ่งมากกว่าผู้สอบไม่ผ่าน 300 คน มีผู้เข้าสอบทั้งหมดจำนวนกี่คน', '["700 คน", "750 คน", "850 คน", "900 คน"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

29. ตอบ 2) 750 คน
ถ้ามีคนสอบ 100 คน หมายความว่า สอบผ่าน 70 คน, สอบไม่ผ่าน 30 คน
ดังนั้น คนสอบผ่านมากกว่าคนสอบไม่ผ่าน = 70 – 30 = 40 คน
จะได้ ถ้ามีคนสอบผ่านมากกว่าคนสอบไม่ผ่าน 40 คน ถ้ามีคนสอบ 100 คน
ถ้ามีคนสอบผ่านมากกว่าคนสอบไม่ผ่าน 300 คน ถ้ามีคนสอบ = 300×100/40
= 30,000/40
= 750 คน', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_030', 'บริษัท ก มีจำนวนพนักงานหญิงเท่ากับพนักงานชาย โดยมีพนักงานชายเป็นโรคอ้วน 30% และพนักงานหญิงเป็นโรคอ้วน 50% บริษัทนี้มีพนักงานเป็นโรคอ้วนร้อยละเท่าไร', '["ร้อยละ 35", "ร้อยละ 40", "ร้อยละ 50", "ร้อยละ 60"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

30. ตอบ 2) ร้อยละ 40
กำหนดให้พนักงานในบริษัทนี้มี 200 คน จะได้ว่ามีพนักงานชาย 100 คน และพนักงานหญิง 100 คน
มีคนเป็นโรคอ้วน = 30 + 50 = 80 คน
ดังนั้น มีคนเป็นโรคอ้วน ร้อยละ = 80/200 × 100 = 40', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_031', 'จำนวนคี่ 3 จำนวนเรียงกัน ถ้า 2 เท่าของจำนวนที่มากที่สุดลบจำนวนน้อยที่สุด คือ -45 แล้วจำนวนที่มากที่สุดมีค่าเท่าไร', '["- 47", "- 49", "- 51", "- 53"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

31. ตอบ 2) -49
แทน 3 จำนวน ดังนี้ x, x+2, x+4
จะได้ 2(x+4) – x = -45
2x + 8 – x = -45
x = -45 – 8 = -53
ดังนั้น จำนวนมากที่สุด = x+4
= -53 + 4 = -49', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_032', 'ตั้ว ต้อง ตาล มีเงินรวมกัน 800 บาท ตั้วมีเงินเป็น 55% ของตาล และต้องมีเงินเป็น 45% ของตาล ต้องการทราบว่าตั้วมีเงินกี่บาท', '["200 บาท", "235 บาท", "220 บาท", "250 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

32. ตอบ 220 บาท
กำหนดให้ ตาลมีเงิน x บาท
ตั้วมีเงิน   (55/100)x บาท
ต้องมีเงิน   (45/100)x บาท
จะได้สมการ x + (55/100)x + (45/100)x = 800
2x = 800
x = 400
ดังนั้น ตั้วมีเงิน = (55/100)x 400 = 220 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_033', 'ปัจจุบัน A อายุ 47 ปี ย้อนกลับไป 3 ปี อายุ A เป็น 4 เท่าของอายุ B อีก 3 ปีข้างหน้า B จะอายุเท่าไร', '["13 ปี", "21 ปี", "17 ปี", "25 ปี"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

33. ตอบ 17 ปี
เวลา A B
3 ปีที่แล้ว 4x = 44 x
ปัจจุบัน 47 14
3 ปีข้างหน้า 50 17', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_034', 'สมานมีเงินเดือน 20,000 บาท เก็บออม 1/4 ของเงินเดือน และค่าห้องพัก 1/3 ของส่วนที่เหลือ จากนั้นจ่ายค่าไฟ 1,500 บาท และให้แม่ 1,800 บาท สมานจะเหลือเงินกี่บาท', '["5,300 บาท", "5,700 บาท", "6,300 บาท", "6,700 บาท"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

34. ตอบ 4) 6,700 บาท
เก็บออม 1/4 × 20,000 = 5,000 บาท ; เหลือเงิน 20,000 – 5,000 = 15,000 บาท
ค่าห้อง 1/3 × 15,000 = 5,000 บาท ; เหลือเงิน 15,000 – 5,000 = 10,000 บาท
ค่าไฟและให้แม่ = 10,000 – 1,500 – 1,800
= 6,700 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_035', 'ถ้า x < y < z และ m เป็นจำนวนเต็มลบ ข้อใดถูกต้อง', '["mx < my < mz", "mx > my > mz", "x/m < y/m < z/m", "m/x < m/y < m/z"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

35. ตอบ 2) mx > my > mz
แทนค่า x = -4, y = -3, z = -2, m = -1
1. mx < my < mz ; (-1)(-4) < (-1)(-3) < (-1)(-2) → 4 < 3 < 2 เท็จ
2. mx > my > mz ; (-1)(-4) > (-1)(-3) > (-1)(-2) → 4 > 3 > 2 จริง
3. x/m < y/m < z/m ; (-4)/(-1) < (-3)/(-1) < (-2)/(-1) → 4 < 3 < 2 เท็จ
4. m/x < m/y < m/z ; (-1)/(-4) < (-1)/(-3) < (-1)/(-2) → 0.25 < 0.33 < 0.5 จริง
จากตัวเลือกที่ 4 ทดลองแทน x = -4, y = -3, z = 4, m = -1
