INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_037', 'ครอบครัวหนึ่งมีสมาชิก 5 คน พ่ออายุ 57 1/4 ปี แม่อายุ 55 2/3 ปี ลูกคนแรกอายุ 26 1/6 ปี ลูกคนที่สองอายุ 18 1/2 ปี และลูกคนสุดท้องอายุ 12 5/6 ปี ครอบครัวนี้มีอายุเฉลี่ยกี่ปี กี่เดือน', '["33 ปี 7 เดือน", "34 ปี 6 เดือน", "35 ปี 2 เดือน", "34 ปี 1 เดือน"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

