พ่อ ; 57 ปี (1/4 × 12 เดือน) = 57 ปี 3 เดือน
แม่ ; 55 ปี (2/3 × 12 เดือน) = 55 ปี 8 เดือน
ลูกคนที่ 1 ; 26 ปี (1/6 × 12 เดือน) = 26 ปี 2 เดือน
ลูกคนที่ 2 ; 18 ปี (1/2 × 12 เดือน) = 18 ปี 6 เดือน
ลูกคนที่ 3 ; 12 ปี (5/6 × 12 เดือน) = 12 ปี 10 เดือน
