= 168 ปี 29 เดือน หรือ 170 ปี 5 เดือน
อายุเฉลี่ย = 170ปี5เดือน/5 = 34 ปี 1 เดือน', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam2', 0);
