ณ คาเฟ่แห่งหนึ่ง มีลูกค้าทั้งหมด 5 คน นั่งโต๊ะละไม่เกิน 2 คน อาชีพของลูกค้าในร้านได้แก่ นางแบบ นักเขียน ดีเจ ติวเตอร์ และโปรแกรมเมอร์ มาจากภูมิลำเนาทั้งหมด 4 จังหวัด ได้แก่ กระบี่ สงขลา นนทบุรี และเชียงใหม่ สั่งเครื่องดื่มไม่ซ้ำกัน 5 อย่าง ได้แก่ ชาเขียว กาแฟ ชาเย็น โกโก้ มอคค่า มีรายละเอียด ดังนี้
- คนสั่งกาแฟนั่งกับคนสั่งชาเขียว
- คนสั่งมอคค่านั่งคนเดียว
- คนสั่งชาเขียวเป็นนางแบบ
- คนสั่งกาแฟเป็นคนสงขลา
- คนสั่งโกโก้เป็นคนจังหวัดเดียวกับคนที่นั่งคนเดียว
- คนนนทบุรีนั่งกับคนสั่งชาเย็น
- คนนนทบุรีเป็นดีเจ
- คนเป็นติวเตอร์ไม่ได้นั่งคนเดียว
- คนนั่งคนเดียวไม่ใช่คนกระบี่
- คนเป็นนักเขียนไม่นั่งคนเดียว
- มีคนมาจากเชียงใหม่

จงเขียนแผนภาพตามเงื่อนไขที่กำหนดให้', '["โต๊ะ 1: กาแฟ (สงขลา, นางแบบ) คู่ ชาเขียว (กระบี่, ดีเจ) | โต๊ะ 2: โกโก้ (นนทบุรี, ติวเตอร์) คู่ ชาเย็น (เชียงใหม่, นักเขียน) | โต๊ะ 3: มอคค่า (สงขลา, โปรแกรมเมอร์)", "โต๊ะ 1: กาแฟ (สงขลา, ติวเตอร์) คู่ ชาเขียว (เชียงใหม่, นางแบบ) | โต๊ะ 2: โกโก้ (กระบี่, ดีเจ) คู่ ชาเย็น (นนทบุรี, นักเขียน) | โต๊ะ 3: มอคค่า (กระบี่, โปรแกรมเมอร์)", "โต๊ะ 1: กาแฟ (นนทบุรี, นักเขียน) คู่ ชาเขียว (สงขลา, นางแบบ) | โต๊ะ 2: โกโก้ (เชียงใหม่, ดีเจ) คู่ ชาเย็น (กระบี่, ติวเตอร์) | โต๊ะ 3: มอคค่า (เชียงใหม่, โปรแกรมเมอร์)", "โต๊ะ 1: กาแฟ (สงขลา, ติวเตอร์/นักเขียน) คู่ ชาเขียว (เชียงใหม่/กระบี่, นางแบบ) | โต๊ะ 2: โกโก้ (นนทบุรี, ดีเจ) คู่ ชาเย็น (เชียงใหม่/กระบี่, ติวเตอร์/นักเขียน) | โต๊ะ 3: มอคค่า (นนทบุรี, โปรแกรมเมอร์)"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

