คิดเป็นลำดับ ดังนี้
1) วาดผังโต๊ะประมาณ 3 – 5 โต๊ะ (เผื่อได้ใช้ครบ)
2) ลงรายละเอียดเครื่องดื่มจาก “กาแฟ” นั่งกับ “ชาเขียว”
3) “มอคค่า” นั่งคนเดียว
4) เพิ่มอาชีพ “นางแบบ” ที่ “ชาเขียว”
5) เพิ่มจังหวัด “สงขลา” ที่ “กาแฟ”
6) เว้นเงื่อนไข คนสั่งโกโก้เป็นคนจังหวัดเดียวกับคนที่นั่งคนเดียว ไว้ก่อนเพราะยังไม่ทราบแน่ชัด
7) เพิ่มข้อมูลอีกโต๊ะว่าคน “นนทบุรี” นั่งกับคนสั่ง “ชาเย็น”
8) แสดงว่ามี 2 โต๊ะที่นั่ง 2 คน และอีก 1 โต๊ะ นั่งคนเดียว และเครื่องดื่มค้างอีก 1 ชนิด คือ “โกโก้” จึงระบุ
เป็นเครื่องดื่มของคนนนทบุรี
9) จากเงื่อนไขที่เว้นไว้ในข้อ 6) จะได้ว่า คนที่นั่งคนเดียว เป็นคน “นนทบุรี”
10) เพิ่มข้อมูล “ดีเจ” ที่ “นนทบุรี”
11) เว้นเงื่อนไข คนเป็นติวเตอร์ไม่ได้นั่งคนเดียว ไว้ก่อนเพราะยังไม่ทราบแน่ชัด
12) เงื่อนไข คนนั่งคนเดียวไม่ใช่คนกระบี่ Xตัดทิ้ง เพราะทราบแล้วว่านนทบุรีX
13) จากเงื่อนไข คนเป็นนักเขียนไม่ได้นั่งคนเดียว จึงสรุปได้ว่า อาชีพที่นั่งคนเดียวคือ “โปรแกรมเมอร์”
14) รายละเอียดอื่นๆที่ยังไม่แน่ชัดเว้นไว้ก่อน', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2565', 'e-Exam2', 0);
