INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_081', 'ฝนทั่งให้เป็นเข็ม : เกี่ยวแฝกมุงป่า :: .... : ....', '["เข็นครกขึ้นภูเขา : งมเข็มในมหาสมุทร", "กำขี้ดีกว่ากำตด : กระดี่ได้น้ำ", "ฆ้องปากแตก : ชักใบให้เรือเสีย", "สุกเอาเผากิน : ลูกผีลูกคน"]', '1', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

81. ตอบ 1) เข็นครกขึ้นภูเขา : งมเข็มในมหาสมุทร ความหมายเหมือนกัน (ทำในสิ่งที่ยากลำบาก, เกินกำลัง)', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["อุปมาอุปไมย"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_082', 'I don’t want .... sugar in my tea.', '["few", "some", "little", "any"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

1. ตอบ 4) any
I don’t want . . . sugar in my tae.
คำแปล : ฉันไม่ต้องการน้ำตาลในชาของฉัน
Sugar หมายถึง น้ำตาล เป็นนามนับไม่ได้
some/little ส่วนใหญ่ใช้กับประโยคบอกเล่า
do not/don’t เป็นประโยคปฏิเสธ ใช้คำบอกจำนวน = any', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_083', 'It was .... hot that I had to take my jacket off.', '["as", "very", "so", "much"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

2. ตอบ 2) very
It was . . . hot that I had to take my jacket off.
คำแปล : มันร้อนจนฉันต้องถอดเสื้อ
คำว่า hot มักถูกใช้ร่วมกับ very hot = ร้อนมาก(ใช้กับสภาพอากาศหรือความรู้สึกร้อน),
so hot = ร้อนแรง (ในเชิงการดึงดูด)', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_084', 'Dr. Shaun .... to hospital by taxi when he lived in Bangkok.', '["go", "goes", "went", "gone"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

3. ตอบ 3) went
Dr. Shaun . . . to hospital by taxi when he lived in Bangkok.
คำแปล : ดร. Shaun ไปโรงพยาบาลด้วยการนั่งเท็กซี่เมื่อตอนที่เขาอยู่กรุงเทพ
จากบริบท : สังเกต “lived” แสดงว่าเกิดขึ้นแล้ว (ในอดีต) จึงใช้ v.2 ของ go คือ went', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_085', 'Either a doctor or a nurse .... in the ambulance last night.', '["is", "are", "was", "were"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

4. ตอบ 3) was
Either a doctor or a nurse . . . in the ambulance last night.
คำแปล : ไม่ว่าหมอก็พยาบาลที่จะต้องอยู่ในรถพยาบาลเมื่อคืนนี้
จาก either . . . or . . . มีกริยาตามนามตัวหลัง (a nurse) สังเกตจาก last night เป็นการบอกเวลาใน
อดีต จึงใช้ was', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_086', 'If I were still young. I .... climb up that mountain.', '["can", "might", "would", "will"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

5. ตอบ 3) would
If I were still young. I . . . climb up that mountain.
คำแปล : ถ้าฉันยังเด็ก ฉันจะปีนขึ้นไปบนภูเขาลูกนั้น
1. can สามารถ 2. might อาจจะ 3. would จะ(ยังไม่เป็นจริง) 4. will จะ', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_087', 'Water boils .... 100 degrees Celsius.', '["in", "on", "at", "above"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

6. ตอบ 3) at
Water boils . . . 100 degrees Celsius.
คำแปล : น้ำเดือด . . . . 100 องศาเซลเซียส
1. in ใน 2. on บน 3. at ที่ 4. above เหนือ', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_088', '.... dress is yours, yellow one or red one ?', '["Either", "What", "Whose", "Which"]', '4', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

7. ตอบ 4) Which
. . . dress is yours, yellow one or red one ?
คำแปล : เดรสตัวไหนที่เป็นของคุณ สีแดงหรือสีเหลือง
1. Either ไม่อันใดก็อันหนึ่ง 2. What อะไร 3. Whose ของใคร 4. Which ชิ้นไหน', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_089', '.... the notebook, that you buy ?', '["Any", "Which", "Much", "None"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

8. ตอบ 2) Which
. . . . the notebook, that you buy ?
คำแปล : สมุดโน้ตอันไหนที่คุณซื้อ
1. Any ใดๆ 2. Which อันไหน 3. Much มาก 4. None ไม่มี', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_090', 'XXXX .... May 2’ 2028', '["in", "on", "at", "among"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

9. ตอบ 2) on
XXXX . . . May 2’ 2028
in ใช้กับเดือน แต่ในโจทย์บอกวันที่แน่นอน จึงตอบ on ซึ่งใช้กับวัน', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_091', 'คำใดมีความหมายใกล้เคียงกับคำว่า “Turn over”', '["pass", "write", "refuse", "finish"]', '3', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

10. ตอบ 3) refuse
Turn over หมายถึง พลิก/คว่ำ/เท
1. pass ผ่าน 2. write เขียน 3. refuse ปฏิเสธ 4. finish จบ', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Vocabulary"]', '2565', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2565_e-Exam2_092', 'My daughter is watching TV, .... she has not finished her homework.', '["nor", "yet", "or", "for"]', '2', 'ข้อสอบจริง ก.พ. ปี 2565 ชุด e-Exam2

11. ตอบ 2) yet
My daughter is watching TV, . . . she has not finished her homework.
