INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_015', '6 * 10 = 100
8 * 9 = 120
4 * 6 = ?', '["40", "56", "64", "72"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

15. ตอบได้ 2 กรณี ขึ้นอยู่กับดุลยพินิจของผู้ออกข้อสอบ ดังนี้
กรณีที่ 1 ตอบ 1) 40
จากความสัมพันธ์ (หน้า × หลัง) × 5/3 = ผลลัพธ์
จะได้ (6 × 10) × 5/3 = 60 × 5/3 = 100
(8 × 9) × 5/3 = 54 × 5/3 = 120
(4 × 6) × 5/3 = 24 × 5/3 = 40
กรณีที่ 2 ตอบ 2) 56
จากความสัมพันธ์ (หน้า × หลัง) + 4(หน้า + 4) = ผลลัพธ์
จะได้ (6 × 10) + 4(6 + 4) = 60 + 40 = 100
(8 × 9) + 4(8 + 4) = 72 + 48 = 120
(4 × 6) + 4(4 + 4) = 24 + 32 = 56', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป", "โอเปอเรชัน"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_016', '5 * 7 = 24
8 * 8 = 0
7 * 12 = ?', '["18", "36", "84", "95"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

16. ตอบ 4) 95
จากความสัมพันธ์ (หลัง)^2 – (หน้า)^2  = ผลลัพธ์
จะได้ 7^2 - 5^2  = 49 – 25 = 24
8^2 – 8^2  = 64 – 64 = 0
12^2 – 7^2  = 144 – 49 = 95', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป", "โอเปอเรชัน"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_017', '10 * 12 = -11
9 * 6 = 5
8 * 10 = ?', '["-9", "-11", "-7", "-6"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

17. ตอบ -9
จากความสัมพันธ์   (หน้า+หลัง)/(หน้า-หลัง) = ผลลัพธ์
จะได้   (10+12)/(10-12) = 22/(-2) = -11
(9+6)/(9-6) = 15/3 = 5
(8+10)/(8-10) = 18/(-2) = -9
