ในปีพ.ศ. 2562 ถั่วรสไก่มียอดขายมากกว่าถั่วรสกุ้ง 50% จะได้อัตราส่วนยอดขายของถั่วรสกุ้ง : ถั่วปากอ้าเท่ากับเท่าไร', '["3 : 4", "4 : 3", "2 : 1", "2 : 3"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

18. ตอบ 1) 3 : 4
จากโจทย์กำหนดให้ถั่วรสไก่มียอดขายมากกว่าถั่วรสกุ้ง 50%
จะได้ว่า ถั่วรสไก่มียอดขาย 150 % เท่ากับ 18 แสนบาท
ถั่วรสกุ้งจะมียอดขาย 100% เท่ากับ 18 × 100/150 = 12 แสนบาท
หาอัตราส่วนยอดขายของถั่วรสกุ้ง : ถั่วปากอ้า เท่ากับ 12 : 16 หรือ 3 : 4', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ตาราง"]', '2566', 'Paper', 0);
