ค่าเฉลี่ยยอดขายของถั่วรสไก่ตั้งแต่ปีพ.ศ. 2560 – 2565 มีค่าเท่ากับ 1.8 ล้านบาท จงหาว่ายอดขายตลอด 6 ปีของถั่วรสไก่มากกว่าถั่วเคลือบรสกะทิกี่บาท', '["2 ล้านบาท", "2.5 ล้านบาท", "3 ล้านบาท", "3.5 ล้านบาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

20. ตอบ 3) 3 ล้านบาท
ผลรวมของยอดขาย 2560 ถึง 2565
ค่าเฉลี่ยของขายถั่วรสไก่ =
6 ปี
18 = (14+24+18+9+X+18)/6
X = (18 × 6) – 83
= 25
ผลรวมยอดขายของถั่วรสไก่ = 83 + 25 = 108 แสนบาท
ผลรวมยอดขายของถั่วเคลือบรสกะทิ = 78 แสนบาท
จะได้ว่ายอดขายตลอด 6 ปีของถั่วรสไก่มากกว่าถั่วเคลือบรสกะทิ = 108 – 78
= 30 แสนบาท หรือ 3 ล้านบาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ตาราง"]', '2566', 'Paper', 0);
