หากยอดขายของถั่วเขียวตั้งแต่ปีพ.ศ. 2560 -2565 มากกว่ายอดขายของถั่วปากอ้าอยู่ 900,000 บาท จงหายอดขายของถั่วเขียวในปีพ.ศ. 2561', '["1.5 ล้านบาท", "1.7 ล้านบาท", "1.9 ล้านบาท", "2.1 ล้านบาท"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

21. ตอบ 2) 1.7 ล้านบาท
กำหนดให้ ยอดขายถั่วเขียนปีพ.ศ. 2561 เท่ากับ X แสนบาท
จาก ยอดขายถั่วเขียวปีพ.ศ. 2560 – 2565 = 21 + X + 13 + 16 + 12 + 20
= 82 + X
ยอดขายถั่วปากอ้าปีพ.ศ. 2560 – 2565 = 12 + 16 + 16 + 8 + 24 + 14 = 90
โจทย์กำหนดให้ ยอดขายถั่วเขียว – ยอดขายถั่วปากอ้า = 9
จะได้ (82 + X) – 90 = 9
X – 8 = 9
X = 17
ดังนั้น ยอดขายของถั่วเขียวในปีพ.ศ. 2561 เท่ากับ 17 แสนบาท หรือ 1.7 ล้านบาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ตาราง"]', '2566', 'Paper', 0);
