INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_025', 'จำนวนคี่ 5 จำนวนเรียงติดกัน ผลบวกเท่ากับ 75 จงหาจำนวนที่มากที่สุด', '["15", "23", "19", "27"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

25. ตอบ 19
วิธีที่ 1 กำหนดให้แต่ละจำนวนเท่ากับ x, x+2, x+4, x+6, x+8
จะได้ 75 = x + (x+2) + (x+4) + (x+6) + (x+8)
75 = 5x +20
5x = 55
x = 55/5 = 11
ดังนั้น จำนวนที่มากที่สุดคือ x + 8 เท่ากับ 11 + 8 = 19
วิธีที่ 2 กรณีข้อมูลเรียงกันเป็นจำนวนคี่ (ตามโจทย์คือ 5 จำนวน) ค่ามัธยฐาน = ค่าเฉลี่ย
จะได้ ค่ามัธยฐาน = ค่าเฉลี่ย = 75/5 = 15
ค่ากลางเท่ากับ 15 ดังนั้นจะได้จำนวนที่เรียงกันดังนี้ 11 13 15 17 19
จำนวนที่มากที่สุดคือ 19', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'Paper', 0);
