INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_027', 'บริษัทแห่งหนึ่งหักเงินสมทบพนักงานร้อยละ 3 ของเงินเดือน และบริษัทจะสมทบให้อีกเท่าตัว ถ้าพนักงานเงินเดือน 16,500 บาท สิ้นปีพนักงานจะมีเงินสมทบรวมกี่บาท', '["6,880 บาท", "16,880 บาท", "11,880 บาท", "21,880 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

