29. ตอบ 3) 30 คน
กาแฟ ชา
150 - x x 170 - x
10
แทนจำนวนคนที่ชอบดื่มทั้งกาแฟและชาเป็น x
จำนวนคนใบบริษัท – จำนวนคนที่ไม่ชอบดื่มทั้งกาแฟและชา = จำนวนคนที่ชอบดื่มกาแฟ + จำนวนคนที่ชอบดื่มชา + จำนวนคนที่ชอบดื่มกาแฟและชา
จะได้สมการ 300 – 10 = (150 - x) + x + (170 - x)
290 = 320 – x
x = 320 – 290 = 30 คน', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'Paper', 0);
