6 = 2x +x +1.8
3x = 4.2
x = 4.2/3 = 1.4
ดังนั้น ท่อนที่ 2 ยาว 1.4 เมตร และท่อนที่ 1 ยาว 2x = 2(1.4) = 2.8 เมตร', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'Paper', 0);
