บุคลากรที่ทำงานเกี่ยวข้องกับการแพทย์และโรงพยาบาล 6 คน ได้แก่ กาญ กุล เกด ปรัชญ์ ปราชญ์ และภูมิ มีรายละเอียดความสัมพันธ์กันดังนี้
- แพทย์ทุกคนที่จบจากมหาวิทยาลัยเชียงใหม่จะทำงานที่โรงพยาบาลมหาราช
