- กาญเป็นอาจารย์สอนนักศึกษาแพทย์ที่มหาวิทยาลัยเชียงใหม่
- กุลจบจากคณะแพทย์มหาวิทยาลัยเชียงใหม่
- เกดเป็นแพทย์ของโรงพยาบาลรามาธิบดี
- ทุกคนที่ทำงานอยู่โรงพยาบาลมหาราชรู้จักกับปรัชญ์และปราชญ์
- ปรัชญ์ทำงานอยู่โรงพยาบาลมหาราช
- ภูมิเป็นเพื่อนกับปรัชญ์
- แพทย์ที่โรงพยาบาลรามาธิบดีไม่รู้จักกับแพทย์โรงพยาบาลมหาราช

