INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_057', 'ข้อใดต่อไปนี้เป็นข้อความลำดับที่ 4', '["โดยเฉพาะผลไม้ที่ออกดอกผลตามฤดูกาล", "อีกทั้งยังแปรรูปเป็นผลิตภัณฑ์อื่น", "เกลือนอกจากปรุงรสแล้วยังถนอมอาหาร", "เพราะช่วยเก็บรักษาอาหารไว้นอกฤดูกาล"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

57. ตอบ 4) เพราะช่วยเก็บรักษาอาหารไว้ฤดูกาล
เรียงลำดับได้ดังนี้ 3 – 2 - 1 – 4 คือ เกลือนอกจากปรุงรสแล้วยังถนอมอาหาร อีกทั้งยังแปรรูปเป็น
ผลิตภัณฑ์อื่น โดยเฉพาะผลไม้ที่ออกดอกผลตามฤดูกาล เพราะช่วยเก็บรักษาอาหารไว้นอกฤดูกาล', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_058', 'ข้อใดต่อไปนี้เป็นข้อความลำดับที่ 3', '["การนำเอาธรรมชาติมาไว้ในสิ่งปลูกสร้างซึ่งมีการพัฒนามาอย่างต่อเนื่อง", "สิ่งก่อสร้างแรกที่เก่าแก่", "คือ สวนลอยบาบิโลน ที่นำเอาต้นปาล์มไปไว้บนตึกอาคารสูงเป็นชั้นๆ", "สถาปัตยกรรมในปัจจุบันมีการนำเอาต้นไม้มาไว้บนอาคารสูง"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

58. ตอบ 2) สิ่งก่อสร้างแรกที่เก่าแก่
เรียงลำดับได้ดังนี้ 4 – 1 – 2 – 3 คือ สถาปัตยกรรมในปัจจุบันมีการนำเอาต้นไม้มาไว้บนอาคารสูง การ
นำเอาธรรมชาติมาไว้ในสิ่งปลูกสร้างซึ่งมีการพัฒนามาอย่างต่อเนื่อง สิ่งก่อสร้างแรกที่เก่าแก่ คือ สวนลอยบาบิโลน
ที่นำเอาต้นปาล์มไปไว้บนตึกอาคารสูงเป็นชั้นๆ', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_059', '“ในอนาคตแรงงานในเอเชียตะวันออกเฉียงใต้จะถูกแทนที่โดยเครื่องจักรกว่า 70% ในอุตสาหกรรมยานยนต์ รถไฟฟ้า เพราะเครื่องจักรมีความแม่นยำมากขึ้นและมีต้นทุนที่ต่ำลง ดังนั้นควรให้การศึกษาแก่เด็กในเรื่องของเทคโนโลยีเพื่อให้ปรับตัวเข้ากับเทคโนโลยีในอนาคต” ข้อใดไม่ถูกต้อง', '["ในอนาคตแรงงานจะถูกเลิกจ้าง", "อุตสาหกรรมยานยนต์มีแนวโน้มใช้เครื่องจักรทดแทนแรงงานคน", "ต้นทุนและความแม่นยำของเครื่องจักรทำให้อุตสาหกรรมเปลี่ยนแปลงอัตราแรงงาน", "ต้องให้เด็กมีการพัฒนาทางการศึกษา เพื่อแข่งขันกับเครื่องจักรในอนาคต"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

59. ตอบ 1) ในอนาคตแรงงานจะถูกเลิกจ้าง เพราะใบบริบทกล่าวถึงเพียงการถูกทดแทน ไม่ใช่การเลิกจ้าง', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_060', '“การยิ้มเป็นการแสดงออกถึงการทักทายรองจากการพูด สำหรับคนที่ไม่ค่อยพูดการยิ้มกับการแสดงออกทางท่าทางออกมา สามารถทำให้ผู้อื่นรับรู้ว่าเรามีความรู้สึกต่อเขาอย่างไร” ข้อความข้างต้นสื่อความหมายว่าอย่างไร', '["การยิ้มหลากหลายอารมณ์", "คนไม่ค่อยพูดจะต้องยิ้มแทนการทักทาย", "การยิ้มควรแสดงออกมาด้วยความจริงใจและควรแสดงท่าทางที่จริงใจด้วย", "ในต่างประเทศใช้การทักทายด้วยคำพูดมากกว่าการยิ้ม"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

