6. ตอบ 3) Help yourself
A : I''m hungry. Can I have some cake? ฉันหิว, ฉันขอกินเค้กได้ไหม
B : Sure, _________? ได้สิ, . . . . .
1. I do ฉันทำ
2. It take easy มันง่ายนะ
3. Help yourself (สำนวน) เชิญตามสบายได้เลย
4. I love it ฉันรักมัน', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["บทสนทนา"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_082', 'John : This is my brother, Nick
Ben : ________.', '["Nice to meet you.", "It’s wonderful.", "That’s your brother.", "This is your brother of kind."]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

7. ตอบ 1) Nice to meet you.
John : This is my brother, Nick. นี่พี่ชายฉันเอง ชื่อนิค
Ben : ________.
1. Nice to meet you. ยินดีที่ได้รู้จัก
2. It’s wonderful. มันยอดเยี่ยมมาก
3. That’s your brother. นั่นคือพี่ชายของคุณ
4. This is your brother of kind. นี่คือพี่ชายที่ใจดีของคุณ', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_083', 'A : ....
B : A cups of tea, please', '["A cup of coffee.", "Do you think about Thai tea?", "Can you make me some tea, please.", "Would you like any drinks?"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

8. ตอบ 4) Would you like any drinks?
A : . . . .
B : A cups of tea, please ขอชาสักแก้วได้ไหม
1. A cup of coffee. กาแฟ 1 แก้ว
2. Do you think about Thai tea? คุณคิดยังไงกับชาไทย
3. Can you make me some tea, please. คุณชงชาให้ฉันสักแก้วได้ไหม
4. Would you like any drinks? คุณต้องการเครื่องดื่มอะไรไหม', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["บทสนทนา"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_084', 'The discovery of the vaccine help to fighting COVID-19.', '["making", "finding", "thinking", "beginning"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

9. ตอบ 2) finding
The discovery of the vaccine help to fighting COVID-19.
คำแปล : การค้นพบวัคซีนช่วยในการต่อสู้กับ โควิด-19
1. making การทำ 2. finding การค้นหา
3. thinking การคิด 4. beginning การเริ่มต้น', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_085', 'If you experience symptoms COVID-19 .... at home at least 5 days.', '["arrive", "isolate", "interest", "aggressive"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

10. ตอบ 2) isolate
If you experience symptoms COVID-19. . . . at home at least 5 days.
คำแปล : ถ้าคุณมีอาการของโรคโควิด-19 ให้ . . . . ที่บ้านอย่างน้อย 5 วัน
1. arrive มาถึง 2. isolate แยกตัว
3. interest สนใจ 4. aggressive ก้าวร้าว', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_086', 'It was her daughter .... placed orders online.', '["who", "which", "when", "what"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

11. ตอบ 1) who
It was her daughter . . . . placed orders online.
คำแปล : ลูกสาวของเธอ . . (เป็นคน) . . สั่งซื้อทางออนไลน์
1. who กล่าวถึงคน 2. which กล่าวถึงสิ่งของ
3. when กล่าวถึงสถานที่ 4. what กล่าวถึงสิ่ง/สถานการณ์', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_087', 'When she wrote her first short story when she .... 25.', '["had", "were", "had been", "was"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

12. ตอบ 4) was
When she wrote her first short story when she . . . 25.
คำแปล : เธอเขียนเรื่องสั้นครั้งแรกเมื่ออายุ 25
ในที่นี้เป็น past simple กล่าวถึงอดีต จึงใช้ was', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_088', 'What the meaning of ‘pursue’ ?', '["cancel", "continue", "complain", "change"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

13. ตอบ 2) continue
pursue หมายถึง การติดตาม
1. cancel ยกเลิก 2. continue ดำเนินต่อ/สืบสาน
3. complain บ่น/ร้องทุกข์ 4. change เปลี่ยน', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Vocabulary"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_089', 'What the meaning of ‘assistance’ ?', '["help", "responsibility", "workload", "senior"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

14. ตอบ 1) help
assistance หมายถึง ความช่วยเหลือ
1. help ความช่วยเหลือ 2. responsibility ความรับผิดชอบ
3. workload งานหนัก 4. senior อาวุโส', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Vocabulary"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_090', 'This dictionary .... more than 1,000 words.', '["contacts", "contains", "comforts", "connect"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

15. ตอบ 2) contains
This dictionary . . . . more than 1,000 words.
คำแปล : พจนานุกรมนี้ . . . . คำศัพท์มากกว่า 1,000 คำ
1. contacts ติดต่อ 2. contains ประกอบด้วย
3. comforts ความสะดวกสบาย 4. connect การเชื่อมต่อ', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_091', 'He trying to avoid .... fatty foods.', '["eat", "eating", "to eat", "ate"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

16. ตอบ 2) eating
He trying to avoid . . . . fatty foods.
คำแปล : เขาหลีกเลี่ยงการ . . (รับประทาน) . . อาหารที่มีไขมันสูง
เนื่องจากคำหน้าคือ avoid + v.ing เป็น gerund คือคำนาม หมายถึง หลีกเลี่ยงการรับประทาน', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_092', 'Mom .... cooking in the kitchen.', '["is", "are", "will", "were"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

17. ตอบ 1) is
Mom . . . . cooking in the kitchen.
คำแปล : แม่ . . . ทำอาหารอยู่ในครัว
ใช้ is เป็น v. to be ของคำว่า mom (แม่) ซึ่งเป็นเอกพจน์', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_093', 'She lost .... handbag.', '["she", "her", "hers", "her’s"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

18. ตอบ 2) her
She lost . . . . handbag.
คำแปล : เธอทำกระเป๋าถือ . . (ของเธอ) . . หาย
การแสดงความเป็นเจ้าของ คือ her + คำนาม ในที่นี้คือ her handbag', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_094', 'By the end of next month, we will have .... this project.', '["comprise", "comparative", "completed", "company"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

19. ตอบ 3) completed
By the end of next month, we will have . . . . this project.
คำแปล : ปลายเดือนหน้า พวกเราจะ . . . . โครงการนี้
1. comprise ประกอบด้วย 2. comparative เปรียบเทียบ
3. completed เสร็จสิ้น 4. company บริษัท', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_095', 'All of the guests were happy to see the bride and groom on the .... decorated stage.', '["beauty", "beauties", "beautiful", "beautifully"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

20. ตอบ 4) beautifully
All of the guests were happy to see the bride and groom on the . . . . decorated stage.
คำแปล : แขกทุกคนมีความสุขที่ได้เห็นเจ้าบ่าวและเจ้าสาวบนเวทีที่ตกแต่งอย่าง . . (สวยงาม) . .
1. beauty (n) 2. beauties (n) 3. beautiful (adj) 4. beautifully (adv)
ใช้ beautifully ซึ่งเป็น adverb ขยายคำว่าตกแต่ง (verb)', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_096', 'The team’s .... was to complete this project before the end of the fiscal year.', '["objective", "convey", "exclusion", "overlook"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

21. ตอบ 1) objective
The team’s . . . . was to complete this project before the end of the fiscal year.
คำแปล : . . . ของทีม คือ ทำโครงการนี้ให้เสร็จก่อนสิ้นปีงบประมาณ
1. objective จุดประสงค์ 2. convey ถ่ายทอด
3. exclusion ข้อยกเว้น 4. overlook มองข้าม', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_097', 'The office .... of 8 full-time employees and 2 part-time employees.', '["connects", "collects", "contrast", "consists"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

22. ตอบ 4) consists
The office . . . . of 8 full-time employees and 2 part-time employees.
คำแปล : ออฟฟิศ . . . . พนักงานฟูลไทม์ (ทำงานเต็มเวลา) 8 คน และพนักงานพาร์ทไทม์ 2 คน
1. connects เชื่อมต่อ 2. collects จัดเก็บ
3. contrast ขัดแย้ง 4. consists ประกอบด้วย', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_098', 'The eye pain .... for a long time. You should get medical help.', '["lasts", "keeps", "leaves", "reaches"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

23. ตอบ 1) lasts
The eye pain . . . . for a long time. You should get medical help.
คำแปล : ปวดตา . . . . เป็นเวลานาน คุณควรไปพบแพทย์
1. lasts กินเวลา 2. keeps เก็บไว้
3. leaves ออกจาก 4. reaches ถึง', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_099', 'People intrude on the natural environment .... wild animals live and breed.', '["who", "where", "whose", "which"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

24. ตอบ 2) where
People intrude on the natural environment . . . . wild animals live and breed.
คำแปล : ผู้คนบุกรุกสิ่งแวดล้อมทางธรรมชาติ . . (บริเวณที่) . . สัตว์ป่าอาศัยและขยายพันธุ์
1. who กล่าวถึงคน 2. where กล่าวถึงสถานที่
3. whose กล่าวถึงคน 4. which กล่าวถึงสิ่งของ', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_100', 'USA, Canada and Mexico .... the 2026 world cup.', '["will host", "hosted", "have hosted", "may have hosted"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

25. ตอบ 1) will host
USA, Canada and Mexico . . . . the 2026 world cup.
คำแปล : สหรัฐอเมริกา, แคนาดา และเม็กซิโก . . . . ถ้วยฟุตบอลโลก ปี 2026
ตอบ will host (จะได้เป็นเจ้าภาพ) ซึ่งเป็นสิ่งที่จะเกิดขึ้นในอนาคต ใช้ future simple tense', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_101', 'Most of our employees XXXX .... the flood.', '["as if", "because", "although", "because of"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

26. ตอบ 4) because of
Most of our employees XXXX . . . . the flood.
คำแปล : พนักงานส่วนใหญ่ของเรา XXXX . . . . น้ำท่วม
1. as if เหมือนกับ 2. because เพราะว่า
3. although แม้ว่า 4. because of เพราะว่า
ใช้ because + ประโยค และใช้ because of + วลีหรือคำ ในบริบทนี้จึงใช้ because of', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_102', 'The sales of surgical masks .... significantly because of the pandemic.', '["achieved", "admitted", "earned", "increased"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

27. ตอบ 4) increased
The sales of surgical masks . . . . significantly because of the pandemic.
คำแปล : คนขายหน้ากากอนามัย . . . . อย่างมีนัยสำคัญเนื่องจากการเกิดโรคระบาด
1. achieved ประสบความสำเร็จ 2. admitted ยอมรับ
3. earned ได้รับ 4. increased เพิ่มขึ้น', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_103', 'What .... you like to do on weekend ?', '["is", "are", "do", "have"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

28. ตอบ 3) do
What . . . . you like to do on weekend ?
คำแปล : คุณชอบทำอะไรในวันหยุด
ตอบ do เนื่องจากถามถึงการกระทำ ไม่ได้ถามถึงความเป็นอยู่ (ถามการเป็นอยู่ตอบ are)', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_104', 'Please listen .... not again.', '["care", "cares", "careful", "carefully"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

29. ตอบ 4) carefully
Please listen . . . . not again.
คำแปล : โปรดฟัง . . . . ไม่มีอีกครั้ง
1. care (n) 2. cares (v) 3. careful (adj) 4. carefully (adv)
ใช้ adverb ขยาย verb (listen) ดังนั้น ภาพรวมคำแปลของประโยคคือ “โปรดฟังให้ดี ไม่มีการพูดอีกครั้ง”', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_Paper_105', 'Painting is one in a favorite hobbies.', '["busy", "best like or best enjoyed", "wrong", "difficult"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด Paper

30. ตอบ 2) best like or best enjoyed
Painting is one in a favorite hobbies.
คำแปล : การระบายสีเป็นหนึ่งในงานอดิเรกที่ชื่นชอบ
1. busy ยุ่ง 2. best like or best enjoyed ชอบและสนุกที่สุด
