INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_029', 'ถนนเส้นหนึ่งยาว 34 กิโลเมตร มีเสาไฟฟ้าห่างกันเสาละ 1,000 เมตร ระหว่างเสาไฟต้องการปลูกต้นไม้ห่างจากเสาฟ้า 200 เมตร และปลูกห่างจากต้นไม้ต้นอื่น 150 เมตร ทั้งสองฝังของถนนเส้นนี้จะปลูกต้นไม้ได้ทั้งหมดกี่ต้น', '["150 ต้น", "170 ต้น", "300 ต้น", "340 ต้น"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

29. ตอบ 4) 340 ต้น
ระยะทาง 34 กิโลเมตร หรือเท่ากับ 34,000 เมตร
จะมีเสาไฟฟ้า = 34,000/1,000 = 34 ช่อง
ระยะห่างแต่ละเสาไฟฟ้า 1,000 เมตร
เว้นระยะปลูกต้นไม้ทั้ง 2 ฝั่ง = 1,000 – 200 – 200 = 600 เมตร
ดังนั้น เหลือระยะทางสำหรับปลูกต้นไม้ 600 เมตร
200 m 150 m 150 m 150 m 150 m 200 m
มีช่องเสาไฟฟ้า 34 ช่อง จะปลูกต้นไม้ได้ 34 × 5 = 170 ต้น
ปลูกต้นไม้ทั้ง 2 ฝั่งถนน ทั้งหมด 170 × 2 = 340 ต้น', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_030', 'ขายที่ดินราคา 1,500,000 บาท แบ่งให้นายหน้า 5% เจ้าของที่ดินจะได้รับเงินกี่บาท', '["1,420,000 บาท", "1,425,000 บาท", "1,430,000 บาท", "1,435,000 บาท"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

30. ตอบ 1,425,000 บาท
นายหน้าจะได้รับเงิน 1,500,000 × 5/100 = 75,000 บาท
เจ้าของที่ดินจะได้รับเงิน 1,500,000 – 75,000 = 1,425,000 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_031', 'สี่เหลี่ยมจตุรัส 4 รูป เรียงเป็นรูปสี่เหลี่ยมผืนผ้าได้ความรอบรูปเป็น 150 นิ้ว พื้นที่ของสี่เหลั้ยมจตุรัสแต่ละรูปมีค่าเท่าไร', '["205 ตารางนิ้ว", "225 ตารางนิ้ว", "240 ตารางนิ้ว", "255 ตารางนิ้ว"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

31. ตอบ 225 ตารางนิ้ว
x x x x
x x
x x x x
กำหนดให้แต่ละด้านยาว x นิ้ว
เรียงกันได้ความยาวรอบรูป 150 นิ้ว = x + x + x + x + x + x + x + x + x +x
10x = 150
x = 15 นิ้ว
พื้นที่รูปสี่เหลี่ยมจตุรัส = ด้าน × ด้าน = 15 × 15 = 225 ตารางนิ้ว', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_032', 'หมู่บ้าน A มีผู้ป่วยครึ่งหนึ่งของหมู่บ้าน B แต่มากกว่าหมู่บ้าน C อยู่ 23 คน ถ้าทั้งหมู่บ้าน A, B และ C มีผู้ป่วยรวมกัน 81 คน อยากทราบว่าหมู่บ้าน B มีผู้ป่วยมากกว่าหมู่บ้าน C กี่คน', '["17 คน", "24 คน", "38 คน", "49 คน"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

32. ตอบ 4) 49 คน
กำหนดให้ หมู่บ้าน A มีผู้ป่วย x คน
หมู่บ้าน B มีผู้ป่วย 2x คน
หมู่บ้าน C มีผู้ป่วย x - 23 คน
จะได้สมการ x + 2x + (x-23) = 81
4x = 104
x = 104/4 = 26
ดังนั้น หมู่บ้าน A มีผู้ป่วย 26 คน
หมู่บ้าน B มีผู้ป่วย 26×2 = 52 คน
หมู่บ้าน C มีผู้ป่วย 26-23 = 3 คน
จะได้ว่า หมู่บ้าน B มีผู้ป่วยมากกว่าหมู่บ้าน C = 52 – 3 = 49 คน', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_033', 'กำหนดให้ 81 = x^4 และ 3,125 = (1/5)^y จงหาค่าของ 2x + y', '["-1", "3", "1", "4"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

33. ตอบ 1 หรือ -11 หรือ 1, -11 (ขึ้นอยู่กับตัวเลือกที่มาพร้อมโจทย์)
จาก 81 = 3^4 และ (-3)^4 → 81 = x^4  → x = 3, -3
จาก 3,125 = (1/5)^y  → 5^5 = (5^(-1))^y → พิจารณาเฉพาะเลขยกกำลัง จะได้ y = -5
แทน x = 3 และ y = -5 ใน 2x + y ; 2(3) – 5 = 6 – 5 = 1
แทน x = -3 และ y = -5 ใน 2x + y ; 2(-3) – 5 = -6 – 5 = -11', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_034', 'กำหนดให้ x = (2ab+10a+4b+20)/(a+2) และ 4y = 4b + 20 จงหาค่าของ x/y', '["2", "0", "4", "5"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

34. ตอบ 2
จาก 4y = 4b+20 จะได้ y = (4b+20)/4 หรือ y = b+5
จาก   (2ab+10a+4b+20)/(a+2) ดึงตัวแปรร่วม จะได้ x = (2a(b+5)+4(b+5))/(a+2)
x = ((b+5)(2a+4))/(a+2)
x = ((b+5)2(a+2))/(a+2)
x = 2 (b+5)
จะได้   x/y =   (2(b+5))/(b+5) = 2', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_035', 'ถนนเส้นหนึ่งมีต้นไม้สองข้างทางตั้งแต่หัวถึงท้ายถนนทั้งหมด 860 ต้น แต่ละต้นห่างกัน 12 เมตร ถนนเส้นนี้ยาวกี่เมตร', '["5,148 เมตร", "5,160 เมตร", "10,308 เมตร", "10,320 เมตร"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

35. ตอบ 1) 5,148 เมตร
ต้นไม้ทั้ง 2 ข้างทาง = 860 ต้น
ต้นไม้ 1 ข้างทาง = 860/2 = 430 ต้น
จะได้สมการ 430 = ระยะทางทั้งหมด/12 + 1
430 – 1 = ระยะทางทั้งหมด/12
ระยะทางทั้งหมด = 429 × 12 = 5,148 เมตร', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_036', 'สินค้าติดป้ายราคา 30,000 บาท ซึ่งได้กำไร 25% ลูกค้าซื้อเงินสดจึงลดให้ 15% ผู้ขายได้กำไรกี่บาทจากการขายสินค้าชิ้นนี้', '["1,000 บาท", "1,500 บาท", "3,000 บาท", "3,500 บาท"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

36. ตอบ 2) 1,500 บาท
ลด 15% คือ   85/100 × 30,000 = 25,500 บาท
หาต้นทุนจาก 125% = 30,000
100% = 30,000×100/125 = 24,000 บาท
ดังนั้น ราคาขาย – ต้นทุน = 25,500 – 24,000 = 1,500 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_037', 'กำหนดให้ a + b = x^2 – y^2 และ ab = x + y แล้ว 1/b + 1/a เท่ากับข้อใด', '["x", "y", "x – y", "x + y"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

37. ตอบ 3) x – y
จาก 1/b + 1/a = ( 1/b × a/a ) + ( 1/a × b/b )
= a/ab + b/ab = (a+b)/ab
แทน a + b ด้วย x^2 – y^2 และแทน ab ด้วย x + y
จะได้ 1/b + 1/a = (a+b)/ab = (x^2-y^2)/(x+y) = ((x-y)(x+y))/(x+y) = x - y', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_038', 'ระฆัง 3 ใบ ใบที่หนึ่งตีทุก 4 นาที ใบที่สองตีทุก 12 นาที ใบที่สามทุก 15 นาที หากเริ่มตีระฆังทั้ง 3 ใบพร้อมกันในครั้งแรก อีกนานเท่าไรจึงจะต้องตีระฆังพร้อมกันทั้งสามใบอีกครั้ง', '["30 นาที", "60 นาที", "120 นาที", "180 นาที"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

38. ตอบ 2) 60 นาที
หาค.ร.น. ของ 4, 12, 15 จาก
4
41215/1315
3
