INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_042', 'จากภาพ จงหาความยาวของ BD

<svg viewBox="0 0 320 135" style="display:block;max-width:300px;width:100%;margin:12px auto;" role="img" aria-label="รูปสามเหลี่ยมมุมฉาก ABC มีเส้นตั้งฉาก BD โดย AD = 9 และ DC = 16"><polygon points="30,105 120,25 290,105" fill="none" stroke="currentColor" stroke-width="2"/><line x1="120" y1="25" x2="120" y2="105" stroke="currentColor" stroke-width="2"/><text x="18" y="112" fill="currentColor" font-size="14" font-weight="bold">A</text><text x="115" y="18" fill="currentColor" font-size="14" font-weight="bold">B</text><text x="295" y="112" fill="currentColor" font-size="14" font-weight="bold">C</text><text x="115" y="123" fill="currentColor" font-size="14" font-weight="bold">D</text><text x="72" y="99" fill="#f59e0b" font-size="13" font-weight="bold">9</text><text x="200" y="99" fill="#f59e0b" font-size="13" font-weight="bold">16</text></svg>(กำหนดให้รูปสามเหลี่ยมมุมฉาก ABC มีมุม B เป็นมุมฉาก และ BD ตั้งฉากกับด้าน AC ที่จุด D โดย AD = 9 และ DC = 16)', '["8", "10", "12", "14"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

