กำหนดให้ AB = x, BC = y, BD = z
จะได้ 9^2 + z^2  = x^2  - - - - (1)
16^2 + z^2  = y^2  - - - - (2)
x^2 + y^2  = 25^2  - - - - (3)
นำ (1) + (2) ; 9^2 + z^2 + 16^2 + z^2  = x^2 + y^2  - - - - (4)
จาก (3) แทน x^2 + y^2 = 25^2 ใน (4) ; 81 + 256 + 2z^2  = 625
2z^2  = 625 – 81 – 256
