INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_043', 'เมื่อ 6 ปีที่แล้ว พ่อมีอายุเป็น 3 เท่าของลูก ถ้าปัจจุบันพ่ออายุ 45 ปี แล้วปัจจุบันลูกจะมีอายุกี่ปี', '["19 ปี", "15 ปี", "23 ปี", "27 ปี"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

