เมื่อ 6 ปีที่แล้ว ลูกอายุ = 39/3 = 13 ปี
ดังนั้น ปัจจุบันลูกอายุ = 13 + 6 = 19 ปี', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_044', 'ปัจจุบันยายอายุ 60 ปี หลานอายุ 12 ปี อีกกี่ปียายจึงจะมีอายุเป็น 3 เท่าของหลาน', '["8 ปี", "10 ปี", "12 ปี", "14 ปี"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

