INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_068', 'จากเงื่อนไขต่อไปนี้ จงตอบคำถามข้อ 68 – 72
อิทธิ สมพร สายใจ สุดารัตน์ พรพรรณ ทั้ง 5 คนไปร่วมงานเลี้ยง โดยทุกคนต้องสวมชุดสีดำ น้ำเงิน แดง หรือชมพูเท่านั้น และทุกคนใส่เครื่องประดับ ทองคำ มุก เพชร คริสตัล คนละ 1 อย่าง มีรายละเอียด ดังนี้
- มีคนใส่เครื่องประดับซ้ำกัน 2 คน
- คนสวมชุดสีน้ำเงิน เลือกใส่เครื่องประดับคริสตัล
- คนสวมชุดสีชมพู ใส่เครื่องประดับมุก
- สมพรและพรพรรณสวมชุดสีเดียวกัน
- สุดารัตน์ไม่ใส่เครื่องประดับเพชรและทองคำ
- อิทธิและสมพรใส่เครื่องประดับทองคำ

ข้อสรุปที่ 1 พรพรรณใส่เครื่องประดับมุก
ข้อสรุปที่ 2 ถ้าสายใจสวมชุดสีชมพู สุดารัตน์จะใส่เครื่องประดับคริสตัล', '["ข้อสรุปทั้งสองเป็นจริง", "ข้อสรุปทั้งสองไม่เป็นจริง", "ข้อสรุปทั้งสองไม่สามารถสรุปได้แน่ชัด", "ข้อสรุปทั้งสองมีผลต่างกัน"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

