ณ ร้านอาหารแห่งหนึ่ง มีอาหาร 3 อย่าง คือ ผัดซีอิ๊ว กะเพราไข่ดาว และคะน้าหมูกรอบ มีเครื่องดื่ม 2 อย่าง คือน้ำกระเจี๊ยบ และน้ำเก๊กฮวย มีของหวาน 2 อย่าง คือ บัวลอย และไอศครีม กลุ่มเพื่อน 5 คน ได้แก่ สามารถ น้ำใจ เมธานนท์ นวพร และอินทรา ทุกคนรับประทานทั้งอาหาร เครื่องดื่ม และของหวาน ดังนี้
- สามารถดื่มน้ำกระเจี๊ยบ
- นวพรกับอินทราเลือกกินอาหารเหมือนกัน
- อินทรากินผัดซีอิ๊ว
- เมธานนท์กินคะน้าหมูกรอบ
- น้ำใจกับอินทราไม่กินไอศครีม
- ไม่น้ำใจกับเมธานนท์ก็นวพรกับอินทราเลือกดื่มน้ำเก๊กฮวย
- เมธานนท์กับสามารถไม่กินบัวลอย
- คนที่กินกะเพราไข่ดาวจะดื่มน้ำกระเจี๊ยบ
- น้ำใจชอบกินน้ำกระเจี๊ยบ

