INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_100', 'จากบทความต่อไปนี้ จงตอบคำถามข้อ 99 – 100
ในสิ่งเดียวกันเราสามารถมีมุมมองความคิดได้ 2 แบบ ทั้งแบบลบและแบบบวก การคิดลบก็มีข้อดีทำให้เราไม่ประมาท รู้จักป้องกันตนเอง แต่ต้องคิดอย่างพอดี ไม่มากจนเกินไป ส่วนการคิดบวกก็มีข้อดีคือทำให้เรามีแรงบันดาลใจ สร้างแรงจูงใจให้กับตัวเองและผู้อื่น ตัวอย่างคลาสสิก คือ แก้วน้ำใบหนึ่งมีน้ำอยู่ครึ่งแก้ว คนคิดลบจะบอกว่ามีน้ำ “แค่” ครึ่งแก้ว ในขณะที่คนคิดบวกจะบอกว่ามีน้ำ “ตั้ง” ครึ่งแก้ว พยางค์เดียวที่แตกต่างกันระหว่างคำว่า “แค่” กับคำว่า “ตั้ง” แต่กลับให้ความรู้สึกที่แตกต่างกันอย่างสิ้นเชิง สะท้อนถึงมุมมองของแต่ละคนอย่างเห็นได้ชัด

บทความข้างต้นเป็นบทความลักษณะใด', '["บทความกระตุ้นจิตสำนึก", "บทความเพื่อการอธิบาย", "บทความเชิงโต้แย้ง", "บทความเชิงวิจารณ์"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

100. ตอบ 2) บทความเพื่อการอธิบาย
บทความกล่าวถึงมุมมองความคิด 2 แบบ และมีการยกตัวอย่างประกอบ จึงถือว่าเป็นการอธิบายเพื่อ
ขยายความให้เข้าใจมากขึ้น', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "บทความ"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_101', 'ข้อใดไม่ได้กล่าวถึงในบทความต่อไปนี้
“โครงการคนละครึ่ง” เป็นหนึ่งในมาตรการที่ดำเนินการโดยรัฐบาล เพื่อกระตุ้นการจับจ่ายใช้สอยภายในประเทศด้วยการแบ่งเบาภาระค่าใช้จ่ายของประชาชนและช่วยเพิ่มสภาพคล่องให้แก่ร้านค้ารายย่อยทั่วประเทศ เป็นการสนับสนุนเศรษฐกิจรากฐานและฟื้นฟูเศรษฐกิจของประเทศทั้งระบบ การลงทะเบียนโครงการคนละครึ่งจะมีด้วยกัน 2 ส่วน คือ การลงทะเบียนรับสิทธิสำหรับประชาชนและการลงทะเบียนโครงการคนละครึ่งสำหรับร้านค้า ผู้เข้าร่วมโครงการคนละครึ่งจะได้รับเงินอุดหนุนจากรัฐบาลไม่เกินวันละ 150 บาท ดำเนินการจ่ายทั้งโครงการสูงสุดไม่เกิน 3,000 บาทต่อคน ตั้งแต่วันที่ 1 กรกฎาคม 2564 ถึง 31 ธันวาคม 2564', '["วัตถุประสงค์ของโครงการ", "ระยะเวลาในการจัดโครงการ", "ผู้ได้รับผลประโยชน์จากโครงการ", "ขั้นตอนการลงทะเบียนเข้าร่วมโครงการ"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

101. ตอบ 4) ขั้นตอนการลงทะเบียนเข้าร่วมโครงการ
แต่ละตัวเลือกถูกกล่าวถึงในบทความ ดังนี้
1. วัตถุประสงค์ของโครงการ – “เพื่อกระตุ้นการจับจ่ายใช้สอยภายในประเทศด้วยการแบ่งเบาภาระ
ค่าใช้จ่ายของประชาชนและช่วยเพิ่มสภาพคล่องให้แก่ร้านค้ารายย่อยทั่วประเทศ ”
2. ระยะเวลาในการจัดโครงการ – “ตั้งแต่วันที่ 1 กรกฎาคม 2564 ถึง 31 ธันวาคม 2564”
3. ผู้ได้รับผลประโยชน์จากโครงการ – “การลงทะเบียนรับสิทธิสำหรับประชาชนและการลงทะเบียน
โครงการคนละครึ่งสำหรับร้านค้า” หมายถึง ประชาชนและร้านค้าเป็นผู้ได้รับผลประโยชน์', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "บทความ"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_102', 'จากบทความต่อไปนี้ ข้อใดคือจุดเด่นของขิง
ขิง สมุนไพรคู่ครัวคนไทยมาช้านาน เป็นพืชสมุนไพรล้มลุก มีลำต้นใต้ดิน เรียกว่า เหง้าหรือแง่ง แตกเป็นกอขึ้นมาจากใต้ดิน แง่งขิงแก่สดจะมีปริมาณสารสำคัญจำพวกโอลีโอเรซิน (oleoresin) สูง ซึ่งเป็นสารที่ทำให้ขิงมีรสชาติเผ็ดร้อน และในน้ำมันหอมระเหยของขิงก็มีสารสำคัญหลายชนิด โดยมีจินเจอร์รอลเป็นส่วนประกอบสำคัญที่ให้กลิ่นรสและความเผ็ดร้อนที่เป็นเอกลักษณ์ นอกจากนี้ยังมี sesquiterpene, bisabolene, Zingerol นิยมนำมาทำเป็นยาสมุนไพร เช่น ขิงแห้ง ขิงผง และใช้เป็นสารแต่งกลิ่นในผลิตภัณฑ์ต่าง ๆ เช่น เครื่องดื่มสมุนไพร สบู่ แชมพู ยาสีฟัน รวมถึงผลิตภัณฑ์เสริมความงามอื่น ๆ เป็นต้น', '["การแปรรูปขิง", "สรรพคุณของขิง", "ยาสมุนไพรจากขิง", "สารสำคัญภายในขิง"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

102. ตอบ 4) สารสำคัญภายในขิง
บทความอธิบายถึงสารสำคัญในขิงแต่ละชนิด รวมถึงการนำไปแปรรูปเพื่อใช้ประโยชน์จากสารสำคัญ
ดังกล่าว', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "บทความ"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_103', 'ข้อใดคือใจความสำคัญของบทความต่อไปนี้
นักวิทยาศาสตร์พบว่าลิงชิมแปนซีรู้จักแสดงความเศร้าโศกกับการตายของญาติพี่น้องได้เช่นเดียวกับมนุษย์ พวกมันรู้จักสางขนและลูบไล้ปรนนิบัติให้แก่ลิงตัวเมียที่ตายและยังคงอยู่กันเงียบ ๆ ไม่คึกคักหลังจากนั้นต่อมาอีกหลายวัน เคยมีผู้พบเห็นลิงตัวเมียบางตัวอุ้มซากลูกที่ตายแล้วไปมาเป็นเวลานานหลายอาทิตย์ นักวิทยาศาสตร์ยังพบอีกว่าลิงแปนซีและมนุษย์มีดีเอ็นเอแบบเดียวกันอยู่มากถึงร้อยละ 99', '["ลิงชิมแปนซีและมนุษย์มีพฤติกรรมเหมือนกัน", "ลิงชิมแปนซีและมนุษย์มีอารมณ์ความรู้สึกเหมือนกัน", "ลิงชิมแปนซีและมนุษย์มีดีเอ็นเอแบบเดียวกันอยู่มากถึงร้อยละ 99", "ลิงชิมแปนซีมีลักษณะทางกายภาพและจิตใจใกล้เคียงกับมนุษย์"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

103. ตอบ 2) ลิงชิมแปนซีและมนุษย์มีอารมณ์ความรู้สึกเหมือนกัน
บทความกล่าวถึงพฤติกรรมของชิมแปนซีที่มีความรู้สึกโศกเศร้าเหมือนกับมนุษย์ โดยปิดท้ายบทความว่า
“ลิงแปนซีและมนุษย์มีดีเอ็นเอแบบเดียวกันอยู่มากถึงร้อยละ 99” ในที่นี้ไม่ตอบตัวเลือกที่ 4 เนื่องจากบทความ
ไม่ได้กล่าวถึงถึงลักษณะทางกายภาพ (ดีเอ็นเอไม่ถือเป็นลักษณะทางกายภาพ เป็นรหัสของยีนภายในเซลล์ที่มอง
ไม่เห็นได้ด้วยตาเปล่า ไม่สามารถจับต้องได้โดยประสาทสัมผัสพื้นฐาน)', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "บทความ"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_104', 'จากข้อความต่อไปนี้ ข้อใดเป็นประโยคลำดับที่ 2', '["เพราะบางครั้งปากแผลปิดแต่ข้างในยังไม่หาย อาจจะอักเสบหรือเป็นบาดทะยักได้", "กรณีปากแผลเล็กแต่ลึก การทำความสะอาดสำคัญมาก", "แผลเล็กลึก เช่น ตะปูตำ ต้องทำความสะอาดลึกลงไป", "เมื่อเกิดบาดแผลขึ้น การล้างทำความสะอาดแผลจะทำให้แผลหายเร็วและลดการอักเสบจากการติดเชื้อได้"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

104. ตอบ 2) กรณีปากแผลเล็กแต่ลึก การทำความสะอาดสำคัญมาก
เรียบเรียงเป็นบทความได้เป็น 4 – 2 – 3 - 1 ดังนี้
เมื่อเกิดบาดแผลขึ้น การล้างทำความสะอาดแผลจะทำให้แผลหายเร็วและลดการอักเสบจากการติดเชื้อได้
กรณีปากแผลเล็กแต่ลึก การทำความสะอาดสำคัญมาก แผลเล็กลึก เช่น ตะปูตำ ต้องทำความสะอาดลึกลงไป
เพราะบางครั้งปากแผลปิดแต่ข้างในยังไม่หาย อาจจะอักเสบหรือเป็นบาดทะยักได้', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "เรียงประโยค"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_105', 'จากข้อความต่อไปนี้ ข้อใดเป็นประโยคลำดับที่ 1', '["บางคนอาจมีอาการปวดตามตัว เพลีย สั่น หรือลุกจากเก้าอี้ลำบาก", "พาร์กินสันเป็นโรคเรื้อรัง โรคความเสื่อมของระบบประสาทที่พบบ่อยที่สุดโรคหนึ่งในผู้สูงอายุ", "อาการของโรคพาร์กินสันจะค่อยเป็นค่อยไป ในระยะแรกผู้ป่วยอาจจะไม่ทราบ", "ส่วนใหญ่มักจะวินิจฉัยได้จากการสังเกตของคนใกล้ชิดว่ามีอาการผิดปกติ"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

105. ตอบ 2) พาร์กินสันเป็นโรคเรื้อรัง โรคความเสื่อมของระบบประสาทที่พบบ่อยที่สุดโรคหนึ่งในผู้สูงอายุ
เรียบเรียงเป็นบทความได้เป็น 2 – 3 – 1 - 4 ดังนี้
พาร์กินสันเป็นโรคเรื้อรัง โรคความเสื่อมของระบบประสาทที่พบบ่อยที่สุดโรคหนึ่งในผู้สูงอายุ อาการของ
โรคพาร์กินสันจะค่อยเป็นค่อยไป ในระยะแรกผู้ป่วยอาจจะไม่ทราบ บางคนอาจมีอาการปวดตามตัว เพลีย สั่น
หรือลุกจากเก้าอี้ลำบาก ส่วนใหญ่มักจะวินิจฉัยได้จากการสังเกตของคนใกล้ชิดว่ามีอาการผิดปกติ', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "เรียงประโยค"]', '2566', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_106', 'จากข้อความต่อไปนี้ ข้อใดเป็นประโยคลำดับที่ 3', '["โรคภัยไข้เจ็บของผู้สูงอายุจึงมากขึ้นตามไปด้วย", "อายุเฉลี่ยของประชากรสูงขึ้นทั้งหญิงและชายเมื่อเทียบกับในอดีต", "เนื่องจากความก้าวหน้าของวิทยาการด้านสุขภาพและสาธารณสุขดีขึ้น", "สิ่งเหล่านี้มีอิทธิพลต่อภาระโรคกระดูกและข้อทั้งสิ้น"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

106. ตอบ 1) โรคภัยไข้เจ็บของผู้สูงอายุจึงมากขึ้นตามไปด้วย
เรียบเรียงเป็นบทความได้เป็น 3 – 2 – 1 - 4 ดังนี้
เนื่องจากความก้าวหน้าของวิทยาการด้านสุขภาพและสาธารณสุขดีขึ้น อายุเฉลี่ยของประชากรสูงขึ้นทั้ง
