1. ตอบ 4) used to
She . . . . be too lazy about exercise but she is going to swim everyday.
คำแปล : หล่อน . . . . ขี้เกียจออกกำลังกายทุกวัน แต่ทุกวันนี้หล่อนไปว่ายน้ำทุกวัน
คำว่า be going + v.infinitive = ตั้งใจ วางแผน คาดการณ์สิ่งที่จะเกิดขึ้นในอนาคต
1. uses ใช้ 2. use ใช้
