INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_110', 'The important conference will be held .... May 2017.', '["in", "on", "at", "from"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

2. ตอบ 1) in
The important conference will be held . . . . May 2017.
