1. in แปลว่า ใน มักใช้ในการกล่าวถึงเดือน
2. on แปลว่า บน มักใช้ในการกล่าวถึงวัน
3. at แปลว่า ที่ มักใช้ในการกล่าวถึงสถานที่หรือเวลา
4. from แปลว่า จาก นอกจากหมายถึงผู้ส่ง อาจใช้ในการกล่าวถึงช่วงเวลาได้เช่นกัน', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'e-Exam1', 0);
