INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_113', 'Most people are not satisfied with what they have, only a .... are.', '["little", "few", "more", "many"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

5. ตอบ 2) few
Most people are not satisfied with what they have, only a . . . . are.
คำแปล : คนส่วนใหญ่ไม่พอใจกับสิ่งที่ตนเองมี มีเพียง . . . . เท่านั้น
1. little แปลว่า เล็ก, น้อย ใช้แสดงจำนวนวนหรือปริมาณที่เล็กน้อยของสิ่งของ
2. few แปลว่า จำนวนน้อย ใช้แสดงตัวเลขหรือปริมาณ
พูดถึงกลุ่มน้อย ในบริบทนี้กล่าวถึงคน
3. more แปลว่า มากกว่า /ยิ่งขึ้น ไม่เหมาะสมกับบริบทของประโยค
4. many แปลว่า จำนวนมาก ไม่เหมาะสมกับบริบทของประโยค
Reading 1
To Max Sullivan
From Martha Reynolds
Subj Conference
Max,
I have been working on the arrangements for our upcoming conference. I''ve looked into
the City Convention Center, and I think it is the most convenient location. It is close to public
transportation and hotels. The accommodations are also striking. The rooms are large, and we
can reserve up to ten meeting rooms. However, the price is almost 50% more than we agreed
we could spend. The other choice is the Mayfield Hotel. Many associations hold their conventions
there. It is a nice place, and the price is reasonable. However, it is not close to the subway. Also,
it is much smaller than the Convention Center. The hotel has only five meeting rooms. But I think
it would be enough, we plan to hold at least three sessions. Please get in touch with me today
to let me know what you think. Reservations are made one week prior to the conference date.
คำแปล (เฉพาะเนื้อหาจดหมาย) :
Max,
ฉันกำลังดำเนินการจัดเตรียมงานประชุมที่จะจัดขึ้นเร็ว ๆ นี้ ฉันได้ตรวจสอบศูนย์การประชุมของเมืองแล้ว
และคิดว่าเป็นสถานที่ที่สะดวกที่สุด เพราะอยู่ใกล้กับระบบขนส่งสาธารณะและโรงแรมต่าง ๆ ที่พักก็ดีเยี่ยม ห้อง
ประชุมกว้างขวางและเราสามารถจองห้องประชุมได้ถึงสิบห้อง อย่างไรก็ตาม ราคาค่อนข้างสูงกว่าที่เราตกลงกันไว้
เกือบ 50% อีกทางเลือกหนึ่งคือโรงแรม Mayfield สมาคมหลายแห่งจัดงานประชุมที่นั่น เป็นสถานที่ที่ดีและราคา
สมเหตุสมผล แต่ไม่ใกล้กับสถานีรถไฟใต้ดิน และมีขนาดเล็กกว่าศูนย์การประชุมมาก โรงแรมมีห้องประชุมเพียง
ห้าห้อง แต่ฉันคิดว่าน่าจะเพียงพอ เพราะเราวางแผนที่จะจัดอย่างน้อยสามช่วงการประชุม กรุณาติดต่อฉันในวันนี้
เพื่อแจ้งความคิดเห็นของคุณ การจองจะทำล่วงหน้าหนึ่งสัปดาห์ก่อนวันประชุม', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Reading"]', '2566', 'e-Exam1', 0);
