INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam1_117', 'Reading 2
Skin diseases are conditions that affect your skin. There are many different types of skin disorders. Allergies, irritants, genetic, makeup, certain diseases, immune system problems and lifestyle factors can cause skin conditions such as acne, mole, itchy skin, small red bumps to widespread rashes. Your skin can be a reflection of your overall health. And as such, changes in the color, texture, or appearance of your skin may signal an issue.
Some skin conditions can be unsightly but harmless. For example, Acne is the most common and best known skin disease, show that the body is trying to eliminate excessive toxins or a result of a hormonal imbalance. Moles are growths that form when skin cells bunch together with surrounding tissue. Most are called common moles and cause no harm. However, if you notice any red flags like an increase in size or change in color. Anyone who notices changes should let their doctor know so that they can screen for skin cancer. Some of these skin disorders only affect people with diabetes, a skin rash may be the first sign of high blood sugar. The rash may be red, reddish-brown or skin tone. Skin inflammation is a common symptom of skin disorders such as psoriasis and eczema. Red splotches on the skin may signify contact dermatitis, an itchy rash often triggered by an allergen. Allergic skin conditions occur when allergens (such as certain foods, animal dander, wool, or soaps) trigger an immune system response with symptoms such as itchiness, redness, and puffy eyes.
Doctors can tell a lot from looking at your skin. Some skin conditions are harmless, while others can cause discomfort and distress, among other symptoms. It is important to remember that no one has to deal with their skin issues alone. Teaming up with a doctor, such as a dermatologist, can help ensure a correct diagnosis the best possible treatment plan.

What is the best title of this passage ?', '["The skin disease treatment.", "The symptoms of skin diseases.", "The genetics of human skin disease.", "The skin and relationship with diseases."]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam1

9. ตอบ 4) The skin and relationship with diseases.
What is the best title of this passage ? หัวข้อที่ดีที่สุดสำหรับบทความนี้คืออะไร
1. The skin disease treatment. การรักษาโรคผิวหนัง
2. The symptoms of skin diseases. อาการของโรคผิวหนัง
3. The genetics of human skin disease. โรคผิวหนังที่เกิดจากพันธุกรรม
4. The skin and relationship with diseases. ผิวหนังและความสัมพันธ์กับโรค', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Reading"]', '2566', 'e-Exam1', 0);
