INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam2_027', 'รูปสี่เหลี่ยมจตุรัสรูปหนึ่ง มีเส้นทแยงมุมยาว 4 นิ้ว ต้องการทราบว่ารูปสี่เหลี่ยมดังกล่าวมีพื้นที่เท่าไร', '["6 ตารางนิ้ว", "10 ตารางนิ้ว", "11 ตารางนิ้ว", "8 ตารางนิ้ว"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam2

27. ตอบ 8 ตารางนิ้ว
4 x
x
จากสูตรพีทาโกรัส c^2  = a^2 + b^2
จะได้ 4^2  = x^2 + x^2
16 = 2x^2
x^2  = 16/2 = 8
x = 2√2
พื้นที่สี่เหลี่ยมจตุรัส = ด้าน × ด้าน = 2√2 × 2√2 = 4×2 = 8 ตารางนิ้ว', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam2_028', 'จำนวนคู่ 5 จำนวนเรียงติดกัน ผลรวมไม่เกิน 115 จงหาจำนวนมากที่สุดที่เป็นไปได้', '["22", "30", "26", "34"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam2

28. ตอบ 26
กำหนด 5 จำนวนเรียงกัน ได้แก่ n, n+2, n+4, n+6, n+ 8
จะได้สมการ n + (n+2) + (n+4) + (n+6) + (n+8) < 115
5n + 20 < 115
5n < 115 – 20
5n < 95
n < 95/5
n < 19
จะได้ n =18 (เป็นจำนวนคู่)
ดังนั้น จำนวนมากที่สุดที่เป็นไปได้ มีค่าเท่ากับ n+8 = 18+8 = 26', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam2_029', 'ซื้อเสื้อราคาโหลละ 1,800 บาท กางเกงตัวละ 250 บาท หากต้องการนำเสื้อและกางเกงมาจัดเป็นชุด และตั้งราคาขายให้ได้กำไร 20% จะต้องขายในราคากี่บาท', '["460 บาท", "480 บาท", "495 บาท", "510 บาท"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam2

29. ตอบ 480 บาท
เสื้อตัวละ 1,800/12 = 150 บาท
กางเกงตัวละ 250 บาท
จัดเป็นชุด จะได้ต้นทุนชุดละ 150 + 250 = 400 บาท
ต้องการกำไร 20% จะต้องขายในราคา 400 × 120/100 = 480 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam2_030', 'จำนวนนับ 3 จำนวน รวมกันได้ 144 ถ้าจำนวนแรกมากกว่าจำนวนที่สองอยู่ 32 และจำนวนที่สองน้อยกว่าจำนวนที่สามอยู่ 25 จงหาจำนวนที่น้อยที่สุด', '["25", "29", "33", "37"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam2

30. ตอบ 29
กำหนดให้ จำนวนที่ 1 เท่ากับ x
จำนวนที่ 2 เท่ากับ y
จำนวนที่ 3 เท่ากับ z
จะได้สมการ x + y + z = 144 - - - (1)
x – y = 32 หรือ x = 32 + y
z – y = 25 หรือ z = 25 + y
แทน x = 32 + y และ z = 25 + y ใน (1)
จะได้ (32+y) + y + (25+y) = 144
3y = 144 – 57
y = 87/3 = 29', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam2_031', 'จำนวน 6 จำนวนเรียงติดกัน ผลรวมเท่ากับ 171 หากเอาจำนวนที่น้อยที่สุดออกไป 1 จำนวน ค่าเฉลี่ยจะเพิ่มขึ้นเท่าไร', '["เพิ่มขึ้น 1.0", "ลดลง 0.5", "เท่าเดิม", "เพิ่มขึ้น 0.5"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam2

31. ตอบ เพิ่มขึ้น 0.5
จาก ค่าเฉลี่ย =   ผลรวมของจานวนทั้งหมด/จานวนทั้งหมด
จะได้ ค่าเฉลี่ย =   171/6 = 28.5
จะได้ว่า 6 จำนวนที่เรียงติดกัน ได้แก่ 26 27 28 29 30 31
ค่าเฉลี่ย = 28.5
นำจำนวนที่น้อยที่สุดออก 1 จำนวน จะเหลือจำนวนเป็น 27 28 29 30 31
จะได้ค่าเฉลี่ยใหม่ เท่ากับ 29 (กรณีเลขเรียงกันทั้งหมด มัธยฐาน/ค่ากลาง = ค่าเฉลี่ย)
ดังนั้น ค่าเฉลี่ยเพิ่มขึ้น 29 – 28.5 = 0.5', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam2_032', 'ในการสอบครั้งหนึ่ง ผู้สอบไม่ผ่านคิดเป็น 19% และมีคนสอบผ่าน 729 คน ในการสอบครั้งนี้มีผู้เข้าสอบทั้งหมดกี่คน', '["800 คน", "850 คน", "900 คน", "950 คน"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam2

32. ตอบ 3) 900 คน
