729 = 81/100 × จำนวนคนเข้าสอบทั้งหมด
จำนวนคนเข้าสอบทั้งหมด = 729×100/81 = 900 คน', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam2_033', 'มีจำนวนเต็มบวกกี่จำนวน ที่หาร 250 ได้ลงตัว', '["7 จำนวน", "8 จำนวน", "9 จำนวน", "10 จำนวน"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam2

