INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam2_034', 'ที่ดิน 1,750 ตารางวา ขายไปตารางวาละ 13,000 บาท จากนั้นนำเงินที่ได้ไปซื้อที่ดินผืนใหม่ ราคาตารางวาละ 11,830 บาท จะได้ที่ดินทั้งหมดกี่ไร่', '["3.5 ไร่", "4 ไร่", "4.5 ไร่", "5 ไร่"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam2

34. ตอบ 4) 5 ไร่
ขายที่ดิน ได้เงิน 1,750 × 13,000 = 22,750,000 บาท
ซื้อที่ดินใหม่ได้   22,750,000/11,830 = 1,923.08 ตารางวา
ที่ดิน 400 ตารางวา เท่ากับ 1 ไร่
ที่ดิน 1,923.08 ตารางวา เท่ากับ   1,923.08×1/400 = 4.8 ไร่ ≈ 5 ไร่', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam2_035', 'ถ้า 2x + 8 = 108 และ (3y-2)/4 = 10 แล้ว x + y มีค่าเท่ากับเท่าใด', '["60", "62", "64", "66"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam2

35. ตอบ 3) 64
2x + 8 = 108   (3y-2)/4 = 10
2x = 108 – 8 3y – 2 = 40
x = 100/2 = 50 3y = 40+2
y = 42/3 = 14
ดังนั้น x + y = 50 +14 = 64', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam2_036', 'กำหนดให้ 1 + 2 + 3 + .... + (t-1) + t = 120 ถ้า t เป็นจำนวนนับ จะมีค่าเท่ากับเท่าใด', '["14", "15", "16", "17"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam2

36. ตอบ 2) 15
ผลรวมของจำนวนทั้งหมด = (จำนวนแรก+จำนวนสุดท้าย) × จานวนทั้งหมด/2
จะได้สมการ 120 = 1 + t (t/2)
120 =   t/2 + t^2/2
0 =   t/2 + t^2/2 – 120
คูณ 2 ทั้งสมการ ; 0 = t^2 + t – 240
0 = (t-15) (t-16)
t = 15, -16 [เลือกตอบ 15 เพราะเป็นจำนวนนับ]', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป", "อนุกรม"]', '2566', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam2_037', 'ห้องเรียนหนึ่งมีนักเรียนหญิงจำนวน 6 คน คิดเป็น 50/3 % ของห้อง ต้องการทราบว่าห้องนี้มีนักเรียนชายจำนวนกี่คน', '["28", "30", "32", "34"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam2

37. ตอบ 2) 30
ร้อยละ 50/3 เท่ากับ 6 คน
ร้อยละ 100 เท่ากับ 6×100/50 = 6×100×3/50 = 1,800/50 = 36 คน
3
ดังนั้น มีนักเรียนชาย เท่ากับ 36 – 6 = 30 คน', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam2_038', 'ข้อมูลกลุ่มหนึ่งมี 35 จำนวน มีค่าเฉลี่ยเท่ากับ 12 ซึ่งข้อมูลดังกล่าวแบ่งออกเป็น 2 ชุด ดังนี้
ชุดที่ 1 มีค่าเฉลี่ยนเท่ากับ 15
ชุดที่ 2 มีค่าเฉลี่ยเท่ากับ 10
จงหาว่าจำนวนข้อมูลชุดที่ 2 มีมากกว่าจำนวนข้อมูลชุดที่ 1 เท่าไร', '["7", "14", "21", "22"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam2

38. ตอบ 1) 7
จาก x̄รวม = ∑Xnรวม/n = (x1̄n1+x2̄n2)/n ∑ Xnรวม = x̄1n1 + x̄2n2 และ nรวม = n1 + n2
รวม  รวม
จะได้ 35 = n1 + n2
จะได้ 12 = (x1̄n1+x2̄n2)/35
n1 = 35 – n2
x̄1n1 + x̄2n2 = 12 × 35
15n1 + 10n2 = 420
หาร 5 ทั้งสมการ ; 3n1 + 2n2 = 84
แทน n1 = 35 – n2 ; 3 (35 – n2) + 2n2 = 84
105 – 3n2 + 2n2 = 84
n2 = 105 – 84 = 21
แทน n2 = 21 จะได้ n1 = 35 – 21 = 14
โจทย์ถามหา n2 – n1 = 21 – 14 = 7', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam2_039', 'สินค้าชิ้นหนึ่งติดป้ายราคาโดยได้กำไร 25% ลูกค้าต่อราคาจึงลดให้ 10% จากราคาป้าย และขายไปในราคา 21,150 บาท ต้องการทราบว่าราคาทุนของสินค้าชิ้นนี้กี่บาท', '["18,800 บาท", "13,800 บาท", "23,800 บาท", "28,800 บาท"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam2

39. ตอบ 18,800 บาท
กำหนดให้ ราคาขาย x บาท
ลด 10% เหลือ 21,150 บาท
จะได้ว่าราคาเดิม เท่ากับ 90/100 ∙ x = 21,150
x = 21,150×100/90 = 23,500 บาท
หาราคาทุนจาก 23,500 = 125/100 × ราคาทุน
ทุน = 23,500×100/125 = 18,800 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam2', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam2_040', 'จากเงื่อนไขต่อไปนี้ จงตอบคำถามข้อ 40 – 44
15 อันดับของประเทศที่มีการผลิตรถยนต์มากที่สุดในโลก ได้แก่ สหรัฐอเมริกา จีน ญี่ปุ่น เยอรมนี เกาหลีใต้ อินเดีย บราซิล เม็กซิโก สเปน อิหร่าน แคนาดา ไทย ฝรั่งเศส อังกฤษ และออสเตรเลีย โดยไม่ได้เรียงลำดับตามข้างต้น แต่เรียงลำดับดังนี้
- เม็กซิโกอยู่อันดับกึ่งกลางระหว่าง 15 ประเทศ
- เกาหลีใต้อยู่ 1 ใน 5 อันดับแรก แต่น้อยกว่าจีน 2 อันดับ
- จีน ญี่ปุ่น และสหรัฐอเมริกา อยู่อันดับติดกัน แต่มิได้เรียงตามที่กล่าว
- กาหลีใต้และอินเดียอยู่อันดับติดกัน
- ไทยอยู่ต่ำกว่าเม็กซิโก 5 อันดับ และอังกฤษอยู่ต่ำกว่าเม็กซิโก 7 อันดับ
- สเปนและฝรั่งเศสอยู่อันดับที่มีเลขคู่
- อิหร่านและแคนาดาอยู่อันดับที่มีเลขคี่
- บราซิลอยู่อันดับสูงกว่าเม็กซิโก
- เกาหลีใต้อยู่อันดับกึ่งกลางระหว่างบราซิลกับจีน
- ออสเตรเลียอยู่อันดับระหว่างฝรั่งเศสกับสเปน

