กรณีที่ 1 ตอบ 1) ซอฟต์แวร์ : คอมพิวเตอร์
สิ่งที่ต้องมีเพื่อให้ชีวิตมนุษย์และคอมพิวเตอร์สำเร็จผล
มนุษย์ทุกคนต้องมีวันเกิด ถึงจะได้ใช้ชีวิต
คอมพิวเตอร์จะต้องมีซอฟต์แวร์ จึงจะสามารถทำงานได้
กรณีที่ 2 ตอบ 3) ศิลาฤกษ์ : อาคาร
วันที่กำเนิดมนุษย์, อาคาร
