ก่อสร้าง (อาจจะมีหรือไม่มีก็ได้)', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["อุปมาอุปไมย"]', '2566', 'e-Exam2', 0);
