INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_024', 'สารชนิดที่หนึ่ง ชนิดที่สอง และชนิดที่สาม ผสมกันในอัตราส่วน 2:3:3 ตามลำดับ สารผสมทั้งสามชนิดมีน้ำหนักรวมกัน 64 กิโลกรัม สารชนิดที่หนึ่งมีน้ำหนักกี่กิโลกรัม', '["12 กิโลกรัม", "16 กิโลกรัม", "24 กิโลกรัม", "28 กิโลกรัม"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

24. ตอบ 2) 16 กิโลกรัม
จากอัตราส่วน จะได้ว่า รวมเท่ากับ 2 + 3 + 3 = 8 ส่วน
สาร 8 ส่วน หนัก 64 กิโลกรัม
สาร 1 ส่วน หนัก   64/8 = 8 กิโลกรัม
ดังนั้น สารชนิดที่หนึ่ง มี 2 ส่วน หนัก 8 × 2 = 16 กิโลกรัม', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_025', 'ปัจจุบัน ก, ข และ ค มีอายุรวมกัน 91 ปี อีก 5 ปีข้างหน้า ก จะมีอายุมากกว่า ค 12 ปี และ ข จะมีอายุเพิ่มขึ้น 20% ปัจจุบัน ก มีอายุกี่ปี', '["37 ปี", "39 ปี", "42 ปี", "48 ปี"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

25. ตอบ 2) 39 ปี
จากโจทย์ จะได้ข้อมูลดังตาราง
ปัจจุบัน อีก 5 ปีข้างหน้า
ก x x + 5
ข y 120  6
y = y
100  5
ค x - 12 x – 12 +5 = x - 7
91 + 3(5)
รวม 91 [3×5 มากจากอายุ 3 คน
เพิ่มคนละ 5 ปี]
จะได้สมการเป็น ผลรวมอายุปัจจุบัน = อายุ ก + อายุ ข + อายุ ค
x + y + x - 12 = 91
2x + y = 103 - - - - (1)
ผลรวมอายุ 5 ปีข้างหน้า = x + 5 + (6/5)y + x – 7
2x + (6/5)y = 108 - - - - (2)
(2) – (1) ; 2x + (6/5)y - (2x + y) = 108 – 103
2x + (6/5)y - 2x - y = 5
(6/5)y – y = 5
y/5 = 5
y = 25
แทน y = 25 ใน (1) ; 2x + 25 = 103
2x = 78
x = 39
ดังนั้น ก มีอายุ 39 ปี', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_026', 'จงหาค่าของ 2^7/16 - 5^4/125', '["1", "2", "3", "5"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

26. ตอบ 3) 3
จากโจทย์ จะได้สมการรูปใหม่เป็น   2^7/2^4 - 5^4/5^3
คุณสมบัติการหารเลขยกกำลัง คือ   a^m/a^n = a^(m-n)
จะได้   2^7/2^4 - 5^4/5^3 = 2^(7-4) - 5^(4-3)  = 2^3 - 5^1  = 8 – 5 = 3', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_027', 'เมื่อ 20 ปีที่แล้ว เกรซและแกรนมีอายุเป็น 1:2 ปัจจุบันเกรซและแกรนมีอายุเป็น 2:3 ปัจจุบันเกรซมีอายุกี่ปี', '["20 ปี", "30 ปี", "40 ปี", "50 ปี"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

27. ตอบ 3) 40 ปี
จากโจทย์ จะได้ข้อมูลดังตาราง
20 ปีที่แล้ว ปัจจุบัน
เกรซ x x + 20
แกรน 2x 2x + 20
เทียบอัตราส่วนอายุปัจจุบัน   เกรซ/แกรน =   2/3 =   (x+20)/(2x+20)
จาก   2/3 =   (x+20)/(2x+20)
คูณไขว้ ; 3x + 60 = 4x + 40
x = 20
ดังนั้น ปัจจุบัน เกรซอายุ x + 20 = 20 + 20 = 40 ปี', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_028', 'ขนมเปียกปูน ชิ้นละ 5 บาท ตะโก้ ชิ้นละ 7 บาท ขนมเทียน ชิ้นละ 10 บาท นาย ก ซื้อขนมเปียกปูนมากกว่าตะโก้ 8 ชิ้น ซื้อขนมเทียนเป็นครึ่งหนึ่งของขนมเปียกปูน โดยจ่ายเงินไปทั้งหมด 114 บาท นาย ก ซื้อขนมรวมกันกี่ชิ้น', '["17 ชิ้น", "18 ชิ้น", "19 ชิ้น", "20 ชิ้น"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

28. ตอบ 1) 17 ชิ้น
แทน จำนวนขนมเปียกปูน เป็น x
แทน จำนวนตะโก้ เป็น y
แทน จำนวนขนมเทียน เป็น z
จะได้สมการ ซื้อขนมเปียกปูนมากกว่าตะโก้ 8 ชิ้น ; x – y = 8 - - - - (1)
ซื้อขนมเทียนเป็นครึ่งหนึ่งของขนมเปียกปูน ; z = x/2 หรือ x = 2z - - - - (2)
ราคาขนม×จำนวนที่ซื้อ = ราคาที่จ่าย ; 5x + 7y + 10z = 114 - - - - (3)
แทน (2) ใน (3) ; 20z + 7y = 114 - - - - (4)
นำ (1) × 7 ; 7x – 7y = 56 - - - - (5)
นำ (4) + (5) ; 20z + 7y + 7x – 7y = 114 + 56
34z = 170
z = 170/34 = 5
แทน z = 5 ใน (2) ; x = 2(5) = 10
แทน x = 10 ใน (1) ; 10 – y = 8 จะได้ y = 2
ดังนั้น ซื้อขนมทั้งหมด x + y + x = 10 + 2 + 5 = 17 ชิ้น', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_029', 'ห้องเรียนหนึ่งมีนักเรียน 40 คน ซึ่ง 3/4 ของนักเรียนห้องนี้เป็นนักเรียนชาย และ 1/3 ของนักเรียนชาย มีส่วนสูงมากกว่า 160 เซนติเมตร ต้องการทราบว่าห้องเรียนนี้มีนักเรียนชายที่สูงกว่า 160 เซนติเมตรกี่คน', '["5 คน", "10 คน", "15 คน", "20 คน"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

