INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_030', 'จงหาผลรวมของ -1 + 2 -3 + 4 - .... -1,219 + 1,220', '["610", "-610", "620", "-620"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

30. ตอบ 1) 610
