ดังนั้น ผลรวมเท่ากับ 1 × 610 = 610', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป", "อนุกรม"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_031', 'ปานทำงานปีที่ 2 ได้รับเงินเดือนเพิ่มขึ้น 5.5% ของเงินเดือนเริ่มต้น ในปีที่ 3 ได้รับเงินเดือนเพิ่มขึ้น 3% จากปีก่อนหน้า ถ้าปีที่ 3 ปานได้รับเงินเดือน 20,050 บาท ในปีที่เริ่มทำงาน ปานได้รับเงินเดือนประมาณกี่บาท', '["18,350 บาท", "18,450 บาท", "18,550 บาท", "18,650 บาท"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

31. ตอบ 2) 18,450 บาท
กำหนดให้ เงินเดือนเริ่มต้น x บาท
ปีที่ 2 เงินเดือน   105.5/100 x บาท
ปีที่ 3 เงินเดือน   103/100 (105.5/100 x) บาท
จะได้สมการ เงินเดือนปีที่ 3 =   103/100 (105.5/100 x)
20,050 =   103/100 (105.5/100 x)
x =   20,050×100×100/103×105.5 = 18,451.2 บาท
ดังนั้น ปีที่เริ่มทำงาน ปานได้รับเงินเดือน ≈ 18,450 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_032', 'มีขนมอยู่ 3 กล่อง กล่อง A มีขนมมากกว่ากล่อง B อยู่ 24 ชิ้น กล่อง B มีขนมมากกว่ากล่อง C อยู่ 36 ชิ้น โดยกล่อง C มีขนม 8 ชิ้น อัตราส่วนของขนมในกล่อง A ต่อกล่อง B ต่อกล่อง C เป็นเท่าไร', '["16:10:1", "17:11:2", "19:10:3", "20:11:4"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

32. ตอบ 2) 17:11:2
จากโจทย์ จะได้ B – C = 36
B – 8 = 36
B = 36 + 8 = 44
แทน B = 44 จะได้ A –B = 24
A – 44 = 24
A = 68
จะได้อัตราส่วน A:B:C เป็น 68:44:8
หาร 4 ทุกตัว (เพื่อให้เป็นอัตราส่วนอย่างต่ำที่สุด) จะได้อัตราส่วน A:B:C เป็น 17:11:2', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_033', 'นาย ก มีเงิน 450 บาท แบ่งให้น้องชายสองคนทั้งหมด โดยน้องคนแรกได้เงินมากกว่าของเท่าของคนที่สองอยู่ 150 บาท หากน้องชายคนแรกนำเงินที่ได้ไปซื้อเสื้อตัวละ 59 บาท น้องชายคนแรกจะเหลือเงินกี่บาท', '["121 บาท", "241 บาท", "291 บาท", "301 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

33. ตอบ 3) 291 บาท
กำหนดให้ น้องคนที่สอง ได้เงิน x บาท
น้องคนแรก ได้เงิน 2x + 150 บาท
จะได้สมการ เงินนาย ก – เงินให้น้องคนแรก – เงินให้น้องคนที่สอง = 0
แทนค่าในสมการ ; 450 – (2x+150) – x = 0
450 – 2x – 150 – x = 0
3x = 300
x = 300/3 = 100 บาท
แทน x = 100 ในจำนวนเงินที่น้องคนแรกได้รับ เท่ากับ 2(100) + 150 = 350 บาท
นำไปซื้อเสื้อ 59 บาท เหลือเงินเท่ากับ 350 – 59 = 291 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_034', 'สินค้าชิ้นหนึ่งราคา 2,850 บาท ติดป้ายลดราคา 20% และใช้คูปองส่วนลดราคาสินค้าชิ้นนี้อีก ทำให้ลูกค้าซื้อสินค้าชิ้นนี้ไปในราคา 1,590 บาท คูปองส่วนลดดังกล่าวมีมูลค่ากี่บาท', '["590 บาท", "650 บาท", "690 บาท", "700 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

34. ตอบ 3) 690 บาท
ลดราคาเหลือ 2,850 × 80/100 = 2,280 บาท
คูปองส่วนลดมีมูลค่า = 2,280 – 1,590 = 690 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_035', 'A ลงทุนเป็น 4 เท่าของ B และ B ลงทุนเป็น 3 เท่าของ C ถ้า A ลงทุน 2,400 บาท แล้ว C จะลงทุนกี่บาท', '["200 บาท", "300 บาท", "400 บาท", "600 บาท"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

35. ตอบ 1) 200 บาท
จาก A ลงทุนเป็น 4 เท่าของ B
จะได้ 2,400 = 4B
B = 2,400/4 = 600 บาท
และ B ลงทุนเป็น 3 เท่าของ C
จะได้ B = 3C
600 = 3C
C = 600/3 = 200 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_036', 'ผู้จัดขายบัตรละครเวทีได้เงิน 3,500 บาท หักภาษี 7% และจ่ายค่าเช่าโรงละคร 980 บาท ผู้จัดจะได้รับเงินสุทธิกี่บาท', '["2,275 บาท", "2,280 บาท", "2,370 บาท", "2,385 บาท"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

36. ตอบ 1) 2,275 บาท
รายได้ 3,500 บาท หักภาษี 7% จะเหลือเท่ากับ 3,500 × (100-7)/100
= 3,500 × 93/100 = 3,255 บาท
จ่ายค่าเช่าโรงละคร จะเหลือเงินสุทธิ เท่ากับ 3,255 – 980 = 2,275 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_037', 'ในการสอบครั้งหนึ่งมีผู้เข้าสอบเป็นครึ่งหนึ่งของผู้สมัครสอบ และมีผู้สอบผ่านเพียง 7% ถ้ารอบนี้มีคนสอบไม่ผ่าน 186 คน ต้องการทราบว่ามีผู้สมัครสอบทั้งหมดกี่คน', '["200 คน", "300 คน", "400 คน", "500 คน"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

37. ตอบ 3) 400 คน
กำหนดให้ มีผู้สมัครสอบ x คน
มีผู้เข้าสอบ   x/2 คน
มีผู้สอบผ่าน 7% แสดงว่ามีผู้สอบไม่ผ่าน 100 – 7 = 93%
จะได้ว่า คนสอบไม่ผ่าน = จำนวนผู้เข้าสอบ × 93/100
186 =   x/2 × 93/100
x =   186×100×2/93 = 400
ดังนั้น มีผู้สมัครสอบจำนวน 400 คน', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_038', 'ค่าเฉลี่ยของ A และ B เท่ากับ 74 ค่าเฉลี่ยของ B และ C เท่ากับ 99 จงหาว่า C – A มีค่าเท่าไร', '["40", "45", "50", "55"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

38. ตอบ 3) 50
จากค่าเฉลี่ย = ∑x/n
พิจารณา A และ B ; 74 = (A+B)/2
A + B = 148 - - - - (1)
พิจารณา B และ C ; 99 = (B+C)/2
B + C = 198 - - - - (2)
(2) - (1) ; B + C – (A + B) = 198 – 148
B + C – A – B = 50
C – A = 50
ดังนั้น C – A มีค่าเท่ากับ 50', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_039', 'A ใช้เงินครึ่งหนึ่งของเงินเดือนเป็นค่าผ่อนบ้าน 1/4 ของเงินเดือนทั้งหมดเป็นค่าอาหาร 1/3 ของเงินเดือนส่วนที่เหลือเป็นค่าเดินทาง มีเงินเหลือ 7,500 บาท A ได้เงินเดือนเท่าไร', '["36,000 บาท", "45,000 บาท", "54,000 บาท", "63,000 บาท"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

39. ตอบ 2) 45,000 บาท
กำหนดให้ เงินเดือน x บาท
ค่าผ่อนบ้าน   (1/2)x บาท
ค่าอาหาร   (1/4)x บาท
จากค่าผ่อนบ้านและค่าอาหาร จะเหลือเงินเท่ากับ x - (1/2)x - (1/4)x = (1/4)x บาท
จะได้ว่าค่าเดินทาง เท่ากับ   1/3 ((1/4)x) = (1/12)x บาท
หาเงินเดือนจาก เงินเดือน – ค่าผ่อนบ้าน – ค่าอาหาร – ค่าเดินทาง = เงินเหลือ
จะได้สมการ x - (1/2)x - (1/4)x - (1/12)x = 7,500
(12x-6x-3x-1x)/12 = 7,500
2x/12 = 7,500
x = 45,000 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_040', 'นาย ก ตอบคำถามข้อสอบชุดหนึ่ง จำนวน 100 ข้อ ได้ทั้งหมด 82 คะแนน จากคะแนนเต็ม 100 คะแนน โดยมีเงื่อนไขว่าหากตอบถูกจะได้รับ 1 คะแนน แต่หากตอบผิดจะถูกลบ 1 คะแนน นาย ก ตอบถูกกี่ข้อ', '["85 ข้อ", "89 ข้อ", "91 ข้อ", "95 ข้อ"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

40. ตอบ 3) 91 ข้อ
กำหนดให้ มีข้อถูก x ข้อ ได้รับ 1(x) คะแนน
มีข้อผิด 100 – x ข้อ ได้รับ -1(100 - x) คะแนน
จะได้สมการเป็น คะแนนข้อถูก + คะแนนข้อผิด = คะแนนที่ได้รับ
x + [-1(100-x)] = 82
x + (-100 + x) = 82
2x – 100 = 82
2x = 182
x = 91
ดังนั้น นาย ก ตอบถูก 91 ข้อ', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_041', 'กำหนดให้ a เป็นจำนวนเต็มที่มีค่ามากที่สุดที่หาร 172 และ 99 แล้วเหลือเศษ 7 และ 9 ตามลำดับ จำนวนใดต่อไปนี้ไม่ใช่ตัวประกอบของ a+5', '["3", "4", "5", "10"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

41. ตอบ 1) 3
จากโจทย์ หาห.ร.ม. ของตัวเลขทั้ง 2 จำนวน โดยนำมาลบเศษออกก่อน
จาก 172 – 7 = 165
99 – 9 = 90
หา ห.ร.ม. ของ 165 และ 90 ได้ดังนี้
5 165 90
3 33 18
11 6
ดังนั้น ห.ร.ม. ของ 165 และ 90 เท่ากับ 5 × 3 = 15
จะได้ a = 15 และ a + 5 = 15 + 5 = 20
ตัวประกอบของ 20 ได้แก่ 1, 2, 4, 5, 10, 20', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_042', 'กิตติมีลูก 4 คน ซึ่งลูกทุกคนอายุห่างกันคนละ 1 ปี ภรรยาของกิตติอายุ 55 ปี ซึ่งน้อยกว่ากิตติ 3 ปี หากอายุของลูกทั้งหมดรวมกันได้เท่ากับอายุของกิตติพอดี ลูกคนที่ 3 จะมีอายุกี่ปี', '["13 ปี", "14 ปี", "15 ปี", "16 ปี"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

42. ตอบ 2) 14 ปี
ภรรยากิตติ อายุ 55 ปี (น้อยกว่ากิตติ 3 ปี) ดังนั้น กิตติอายุ 55 + 3 = 58 ปี
กำหนดให้ ลูกคนที่ 4 อายุ x ปี
ลูกคนที่ 3 อายุ x+1 ปี
ลูกคนที่ 2 อายุ x+2 ปี
ลูกคนที่ 1 อายุ x+3 ปี
จะได้สมการ อายุลูกรวมกัน = อายุพ่อ
x + (x+1) + (x+2) + (x+3) = 58
4x + 6 = 58
4x = 52
x = 52/4 = 13
ดังนั้น ลูกคนที่ 3 อายุ x + 1 เท่ากับ 13 + 14 = 14 ปี', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_043', 'รถ 2 คัน อยู่ห่างกัน 110 กิโลเมตร ถ้ารถคันที่ 1 วิ่งด้วยความเร็ว 10 กิโลเมตรต่อนาที และรถคันที่ 2 วิ่งด้วยความเร็ว 12 กิโลเมตรต่อนาที หากรถทั้งสองคันเริ่มต้นวิ่งพร้อมกันที่เวลา 10.00 น. รถทั้งสองคันจะสวนกันในเวลากี่โมง', '["10.05 น.", "10.50 น.", "15.05 น.", "15.50 น."]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

43. ตอบ 1) 10.05 น.
จากสูตร v = s/t หรือ s = vt
กำหนดให้ t1 = t2
ระยะทางรวม เท่ากับ 110 กิโลเมตร
sรวม = s1 + s2
จะได้ 110 = v1t + v2t
110 = 10t + 12t
110 = 22t
t = 110/22 = 5 นาที
ดังนั้น รถทั้งสองคันจะวิ่งสวนกันที่เวลา 10.00 + 5 นาที = 10.05 น.', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_044', 'นางสาว ก ซื้อของใช้รวมเป็นเงิน 661 บาท โดยซื้อน้ำมันพืช 2 ขวด ขวดละ 89 บาท ซื้อน้ำยาล้างจาน 3 ถุง ถุงละ 28 บาท ที่เหลือซื้อยาสีฟันกล่องละ 57 บาท นางสาว ก ซื้อของใช้ไปทั้งหมดกี่ชิ้น', '["10 ชิ้น", "12 ชิ้น", "14 ชิ้น", "16 ชิ้น"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

44. ตอบ 2) 12 ชิ้น
ซื้อน้ำมันพืช 2 ขวด ขวดละ 89 บาท เท่ากับ 89 × 2 = 178 บาท
ซื้อน้ำยาล้างจาน 3 ถุง ถุงละ 28 บาท เท่ากับ 28 × 3 = 84 บาท
เหลือเงิน 661 – 178 – 84 = 399 บาท
ยาสีฟัน กล่องละ 57 บาท จะซื้อยาสีฟันได้ 399/57 = 7 กล่อง
ดังนั้น นางสาว ก ซื้อของใช้ทั้งหมด 2 + 3 + 7 = 12 ชิ้น', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_045', 'ถ้ารูปสี่เหลี่ยมจตุรัสมีความยาวแต่ละด้านเพิ่มขึ้น 20% จะมีพื้นที่เพิ่มขึ้นกี่เปอร์เซ็นต์', '["10%", "40%", "44%", "50%"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

45. ตอบ 3) 44%
กำหนดให้ความยาวแต่ละด้านของสี่เหลี่ยมจตุรัส = x หน่วย
พื้นที่เดิม = ด้าน × ด้าน = x^2 ตารางหน่วย
ถ้าความยาวเพิ่มขึ้นด้านละ 20%
จะได้พื้นที่ใหม่ เท่ากับ ((120/100)x)^2  ตารางหน่วย
พื้นที่ที่เพิ่มขึ้น เท่ากับ   (พื้นที่ใหม่-พื้นที่เก่า)/พื้นที่เก่า × 100%
6/5
=   ((x)^2-x^2)/x^2 × 100
36/25
=   (x^2-x^2)/x^2 × 100
36/25   25/25
=   (x^2-x^2)/x^2 × 100
11/25
=   x^2/x^2 × 100 = 44%', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_046', 'A และ B ทำงานร่วมกัน 1 งาน ใช้เวลา 15 วัน ถ้า A ทำงานคนเดียวจะใช้เวลา 24 วัน ถ้า B ทำงานคนเดียวจะใช้เวลากี่วัน', '["20 วัน", "35 วัน", "36 วัน", "40 วัน"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

46. ตอบ 4) 40 วัน
วิธีที่ 1 : เวลาที่ใช้ช่วยกันทำงาน =   เวลาคนที่1×เวลาคนที่2/(เวลาคนที่1+เวลาคนที่2)
จะได้ 15 =   24×B/(24+B)
360 + 15(B) = 24 × B
B =   (360+15B)/24 = 15 + (15/24)B
B - (15/24)B = 15
B =   15×24/9 = 40 วัน
วิธีที่ 2 : A กับ B ทำงาน 15 วัน ได้ 1 งาน
A กับ B ทำงาน 1 วัน ได้   1/15 งาน
A ทำงาน 24 วัน ได้ 1 งาน
A ทำงาน 1 วัน ได้   1/24 งาน
B ทำงาน x วัน ได้ 1 งาน
B ทำงาน 1 วัน ได้   1/x งาน
A กับ B = งาน A + งาน B
1/15 =   1/24 + 1/x
1/x =   1/15 - 1/24
1/x = (1/15 × 8/8) – (1/24 × 5/5)
= 8/120 - 5/120 = 3/120 = 1/40
จาก 1/x = 1/40 ดังนั้น x = 40 วัน', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'e-Exam3', 0);
