สมศักดิ์ซื้อชั้นวางของมา 1 ตู้ มีทั้งหมด 3 ชั้น แบ่งเป็นชั้นบน ชั้นกลาง และชั้นล่าง แต่ละชั้นแบ่งออกเป็น 3 ช่อง โดยเรียงเลขช่อง 1-3 จากซ้ายไปขวา ซึ่งสิ่งของที่นำไปวางได้แก่ ยาสีฟัน สบู่ กระดาษชำระ น้ำยาล้างจาน ผงซักฟอก น้ำอัดลม แชมพู โฟมล้างหน้า และขนม โดยวางสิ่งของ ดังนี้
- โฟมล้างหน้าวางไว้ช่องกลางชั้นล่างสุด
- กระดาษชำระวางไว้ช่องขวาสุดชั้นบน
