- ขนมจะวางอยู่ใต้ช่องใส่น้ำอัดลม
- น้ำอัดลมวางอยู่ใต้ช่องใส่กระดาษชำระ
- น้ำยาล้างจานและผงซักฟอกวางติดกัน

