INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_095', 'We don’t have to go class, .... do we have to do homework.', '["so", "nor", "as", "or else"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

2. ตอบ 2) nor
We don’t have to go class, . . . . do we have to do homework.
