INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_096', 'The train .... 9.00 a.m.', '["depart", "departs", "departure", "departures"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

3. ตอบ 2) departs
depart (v) หมายถึง ออกเดินทาง, ออกจาก departure (n) หมายถึง การออกเดินทาง
ในที่นี้ The train . . . . 9.00 a.m. หมายถึง รถไฟออกเดินทางเวลา 9.00 น.
ใช้ departs เนื่องจากบริบทของประโยคคือ รถไฟ (นามเอกพจน์) + ออกเดินทาง (กริยาต้องเติม s)
จะใช้ departure แทนคำนาม เช่น departure board, your departure', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_097', 'She will not .... because she late for work.', '["promoted", "provided", "processing", "probably"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

4. ตอบ 1) promoted
She will not . . . . because she late for work.
คำแปล : หล่อนจะไม่ได้รับการโปรโมท(คล้ายการเลื่อนขั้น) เพราะหล่อนทำงานช้า
1. promoted ได้รับการโปรโมท (เลื่อนขั้นในการทำงาน)
2. provided ถูกจัดให้, ได้รับ
3. processing การประมวลผล, อยู่ในขั้นตอน
4. probably เป็นไปได้', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_098', 'Somsak : thank you so much for help me join membership, your ***** helpful!
Somsri : ....', '["My condolences.", "It''s too bad.", "You''re welcome.", "It''s my fault."]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

5. ตอบ 3) You''re welcome.
Somsak : thank you so much for help me join membership, your ***** helpful!
Somsri : . . . .
สมศักดิ์ : ขอบคุณมากที่ช่วยฉันให้เข้าร่วมสมาชิก, ***** ของคุณช่วยฉันได้มากๆ
สมศรี : . . . .
1. My condolences. เสียใจด้วยนะ
2. It''s too bad. มันแย่มาก
3. You''re welcome. ด้วยความยินดี
4. It''s my fault. มันเป็นความผิด/ข้อเสียของฉัน', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["บทสนทนา"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_099', 'You can’t lose weight unless you .... exercise.', '["rarely", "recently", "regularly", "reasonable"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

6. ตอบ 3) regularly
You can’t lose weight unless you . . . . exercise.
คำแปล : คุณไม่สามารถลดน้ำหนักได้ ยกเว้นคุณ . . . . ออกกำลังกาย
1. rarely ไม่ค่อย 2. recently เร็วๆนี้
3. regularly อย่างสม่ำเสมอ 4. reasonable มีเหตุผล', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2566', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_100', 'Younger man decided accept a job ....', '["offer", "announce", "application", "invitation"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

7. ตอบ 1) offer
