INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_109', 'นาย ก เป็นเจ้าหน้าที่กรมป่าไม้ ในขณะที่กำลังขับรถตรวจคนมาตัดไม้ ระหว่างนั้นได้ขับรถชนบุคคลภายนอก ซึ่งนาย ก ขับโดยประมาทเลิกเล่อเท่านั้น และได้ชดใช้ค่าเสียหายให้แก่คนที่โดนรถชนเรียบร้อยแล้ว นาย ก มีสิทธิ์อย่างไรตามพระราชบัญญัติความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539', '["ไม่มีสิทธิ์ เพราะนาย ก จ่ายเองโดยพลการ ไม่ได้แจ้งต่อหน่วยงานของรัฐ", "ไม่มีสิทธิ์ เพราะ นาย ก ชดใช้ค่าเหียหายแล้ว ถือว่าหนี้เป็นอันระงับไป", "มีสิทธิ์เรียกให้หน่วยงานของรัฐชดใช้ค่าเสียหายภายใน 10 ปี", "มีสิทธิ์เรียกให้หน่วยงานของรัฐชดใช้ค่าเสียหายภายใน 1 ปี นับแต่วันที่ชดใช้ค่าเสียหาย"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

