9. ตอบ 3) ใบเตือนให้กระทำตามกฎหมาย
คำสั่งทางปกครอง หมายถึงคำสั่งที่ส่งผลต่อสถานภาพของสิทธิหรือหน้าที่ของบุคคล
1. ใบอนุญาตให้สร้างอาคาร – มีผลต่อผู้ที่จะสร้างอาคาร
2. เลื่อนขั้นเงินเดือนของข้าราชการ – มีผลต่อข้าราชการที่จะเลื่อนเงินเดือน
3. ใบเตือนให้กระทำตามกฎหมาย – เป็นการเตือนที่ยังไม่ได้ส่งผลต่อสิทธิหรือหน้าที่ของผู้ถูกเตือน
4. ใบประเมินภาษีอากร – ส่งผลต่อผู้ถูกประเมิน โดยมีหน้าที่ต้องชำระภาษี', 'ความรู้และลักษณะการเป็นข้าราชการที่ดี', 'กพ ภาค ก', 0, 'กฎหมาย', '["พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง"]', '2566', 'e-Exam3', 0);
