INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_e-Exam3_121', 'สภาวิชาชีพบัญชี เป็น “หน่วยงานของรัฐ” ที่ต้องรับผิดทางการละเมิดตามพระราชบัญญัติความรับผิดชอบทางการละเมิดของเจ้าหน้าที่ พ.ศ. 2539 หรือไม่', '["เป็น เนื่องจากเป็นหน่วยงานอื่นของรัฐที่มีพระราชกฤษฎีกากำหนด", "เป็น เนื่องจากเป็นหน่วยงานอื่นของรัฐที่มีพระราชบัญญัติกำหนด", "ไม่เป็น เนื่องจากสภาวิชาชีพไม่ใช่หน่วยงานของรัฐตามความหมายของพระราชบัญญัติความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539", "ไม่เป็น เนื่องจากสภาวิชาชีพเป็นหน่วยงานอื่นของรัฐที่จัดตั้งตามประมวลกฎหมายแพ่งและพาณิชย์"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด e-Exam3

