INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_รอบพิเศษ_005', 'หมูและไก่นับขารวมกันได้ 120 ขา ถ้ามีหมูมากกว่าสองเท่าของไก่อยู่ 5 ตัว มีหมูและไก่รวมกันทั้งหมดกี่ตัว', '["25 ตัว", "35 ตัว", "45 ตัว", "55 ตัว"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด รอบพิเศษ

5. ตอบ 2) 35 ตัว
วิธีคิด กำหนดให้ มีหมู x ตัว, มีไก่ y ตัว
จะได้สมการ x – 2y = 5 - - - - (1)
4x + 2y = 120 - - - - (2)
(1) + (2) ; x – 2y + 4x + 2y = 5 + 120
5x = 125
x = 125/5 = 25
แทน x = 25 ใน (1); 25 – 2y = 5
2y = 20
y = 20/2 = 10
ดังนั้น มีหมู 25 ตัว และมีไก่ 10 ตัว, มีหมูและไก่รวมกัน = 25+10 = 35 ตัว', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'รอบพิเศษ', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_รอบพิเศษ_006', 'นาย ก พิมพ์เอกสารเสร็จ 1 หน้า ในเวลา 15 นาที นาย ข พิมพ์เอกสารเสร็จ 1 หน้า ในเวลา 9 นาที หากกำหนดให้ทั้งสองคนมีเวลาทำงาน 270 นาที นาย ข จะพิมพ์เอกสารได้มากกว่านาย ก กี่หน้า', '["10 หน้า", "11 หน้า", "12 หน้า", "15 หน้า"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด รอบพิเศษ

