นาย ข พิมพ์เอกสารได้มากกว่านาย ก = 30 – 18 = 12 หน้า', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'รอบพิเศษ', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_รอบพิเศษ_007', 'สินค้าชิ้นหนึ่งติดป้ายราคา 13,200 บาท ซึ่งได้กำไร 20% ต่อมามีลูกค้ามาซื้อจึงลดให้ 15% จากราคาป้าย ในการขายสินค้าชิ้นนี้ได้กำไรหรือขาดทุนเท่าไร', '["ขาดทุน 2%", "ขาดทุน 5%", "ได้กำไร 2%", "ได้กำไร 5%"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด รอบพิเศษ

7. ตอบ 3) ได้กำไร 2%
วิธีคิด วิธีที่ 1 ราคาขาย 13,200 บาท เท่ากับ 120/100 (มาจากการได้กำไร 20%)
หาราคาทุนจาก ทุน × 120/100 = 13,200 จะได้ ทุน = 11,000 บาท
ลด 15% จะได้ 13,200 × 85/100 = 11,220 บาท
ดังนั้น ได้กำไรเท่ากับ 11,220 – 11,000 = 220 บาท
คิดเป็น 220 × 100/11,000 = 2%
วิธีที่ 2 กำหนดให้ขาย 85/100 % จากราคาเต็ม 120%
จะได้ 85/100 × 120 = 102 → แสดงว่าได้กำไร 2%', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2566', 'รอบพิเศษ', 0);
