INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_รอบพิเศษ_040', 'หากคณะรัฐมนตรีกำลังรอคณะรัฐมนตรีที่แต่งตั้งใหม่มาปฏิบัติหน้าที่ แต่นายกรัฐมนตรีไม่อาจปฏิบัติราชการได้ เนื่องจาก ตาย ขาดคุณสมบัติ พิพาษให้จำคุก สภาผู้แทนมีมติไม่ไว้วางใจ ศาลรัฐธรรมนูญวินิจฉัยว่าความเป็นนายกรัฐมนตรีสิ้นสุดลง หรือวุฒิสภามีมติให้ถอดถอนจากตำแหน่ง จะให้ผู้ใดมาปฏิบัติหน้าที่แทน', '["คณะรัฐมนตรีมอบหมายรองนายกคนใดคนหนึ่งปฏิบัติหน้าที่แทน", "คณะรัฐมนตรีมอบหมายรองนายกคนใดก็ได้ปฏิบัติหน้าที่แทน", "คณะรัฐมนตรีมอบหมายเลขาธิการนายกรัฐมนตรีปฏิบัติหน้าที่แทน", "คณะรัฐมนตรีมอบหมายปลัดสำนักนายกรัฐมนตรีปฏิบัติหน้าที่แทน"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด รอบพิเศษ

