INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_รอบพิเศษ_041', 'คณะกรรมการมาตรฐานจริยธรรมมีหน้าที่เสนอแนะและให้คำปรึกษาแก่คณะรัฐมนตรีเกี่ยวกับนโยบายและยุทธศาสตร์ด้านจริยธรรม ตีความวินิจฉัยปัญหาอันเกิดจากพระราชบัญญัติมาตรฐานทางจริยธรรม พ.ศ.2562 ใช่หรือไม่', '["ใช่ เป็นหน้าที่ของคณะกรรมการมาตรฐานจริยธรรม", "ไม่ใช่ เป็นหน้าที่ของคณะกรรมการข้าราชการพลเรือน", "ไม่ใช่ เป็นหน้าที่ของคณะรัฐมนตรี", "ไม่ใช่ เป็นหน้าที่ของคณะกรรมการวินิจฉัยข้อพิพาท"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด รอบพิเศษ

10. ตอบ 1) ใช่ เป็นหน้าที่ของคณะกรรมการมาตรฐานจริยธรรม
อ้างอิงตามพระราชบัญญัติมาตรฐานทางจริยธรรม พ.ศ. 2562 มาตรา 13 (1)', 'ความรู้และลักษณะการเป็นข้าราชการที่ดี', 'กพ ภาค ก', 0, 'กฎหมาย', '["พ.ร.บ.มาตรฐานทางจริยธรรม"]', '2566', 'รอบพิเศษ', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_รอบพิเศษ_042', 'ข้อใดสอดคล้องกับมาตรฐานจริยธรรมในหัวข้อตัดสินใจในสิ่งที่ถูกต้องชอบธรรม', '["ปฏิบัติหน้าที่ด้วยความมุ่งมั่นเพื่อให้บรรลุผลตามที่กำหนด", "รายงานและเปิดเผยบุคคลที่กระทำความผิด", "มีจิตสำนึกที่ดีต่อสังคม", "ปฏิบัติหน้าที่ด้วยความเต็มใจ และเท่าเทียม"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด รอบพิเศษ

11. ตอบ 2) รายงานและเปิดเผยบุคคลที่กระทำความผิด
อ้างอิงตามพระราชบัญญัติมาตรฐานทางจริยธรรม พ.ศ. 2562 มาตรา 5', 'ความรู้และลักษณะการเป็นข้าราชการที่ดี', 'กพ ภาค ก', 0, 'กฎหมาย', '["พ.ร.บ.มาตรฐานทางจริยธรรม"]', '2566', 'รอบพิเศษ', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_รอบพิเศษ_043', 'ก่อนเริ่มดำเนินการ ส่วนราชการต้องจัดให้มีการศึกษาวิเคราะห์ผลดีผลเสียอยู่ในเป้าหมายใดของพระราชกฤษฎีกาว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546', '["เพื่อให้เกิดประโยชน์สุขแก่ประชาชน", "เพื่อให้เกิดผลสัมฤทธิ์ต่อภารกิจรัฐ", "มีการประเมินราชการอย่างสม่ำเสมอ", "เพื่อลดขั้นตอนการปฏิบัติงาน"]', '1', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด รอบพิเศษ

12. ตอบ 1) เพื่อให้เกิดประโยชน์สุขแก่ประชาชน
อ้างอิงตามพระราชกฤษฎีกาว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ.2546 มาตรา 8 (3)', 'ความรู้และลักษณะการเป็นข้าราชการที่ดี', 'กพ ภาค ก', 0, 'กฎหมาย', '["พ.ร.ฎ.การบริหารกิจการบ้านเมืองที่ดี"]', '2566', 'รอบพิเศษ', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_รอบพิเศษ_044', 'นาย ก เป็นตำรวจ รับสินบนจากนาย ข มีความผิดฐานใดตามประมวลกฎหมายอาญา หมวด 2 ความผิดต่อตำแหน่งหน้าที่ราชการ', '["นาย ข ผิดฐานให้สินบนพนักงาน", "นาย ข ผิดฐานให้สินบนพนักงาน และสนับสนุน", "นาย ข ไม่มีความผิด นาย ก มีความผิดฐานรับสินบน", "นาย ก และนาย ข ไม่มีความผิด"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด รอบพิเศษ

13. ตอบ 3) นาย ข ไม่มีความผิด นาย ก มีความผิดฐานรับสินบน
โจทย์พูดถึงความผิดในส่วนของเจ้าพนักงาน จึงตอบตัวเลือกที่ 3', 'ความรู้และลักษณะการเป็นข้าราชการที่ดี', 'กพ ภาค ก', 0, 'กฎหมาย', '["กฎหมายอาญา (ความผิดต่อตำแหน่งหน้าที่)"]', '2566', 'รอบพิเศษ', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_รอบพิเศษ_045', 'กรณีไม่มีผู้ว่าราชการจังหวัดหรือมีแต่ไม่อาจปฏิบัติราชการได้ ผู้ใดมีหน้าที่รักษาราชการแทน', '["ปลัดจังหวัด", "รองผู้ว่าราชการจังหวัด", "ปลัดอำเภอ", "นายอำเภอ"]', '2', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด รอบพิเศษ

14. ตอบ 2) รองผู้ว่าราชการจังหวัด
อ้างอิงตามพระราชบัญญัติระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534 มาตรา 56', 'ความรู้และลักษณะการเป็นข้าราชการที่ดี', 'กพ ภาค ก', 0, 'กฎหมาย', '["พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน"]', '2566', 'รอบพิเศษ', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_รอบพิเศษ_046', 'ข้อใดสำคัญต่อการดำเนินการจัดซื้อจัดจ้างของส่วนราชการ', '["รวดเร็ว เป็นธรรม", "ประโยชน์และผลเสียต่อสังคม", "คำนึงถึงการลดค่าใช้จ่าย", "เปิดเผย เที่ยงธรรม"]', '4', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด รอบพิเศษ

15. ตอบ 4) เปิดเผย เที่ยงธรรม
อ้างอิงตามพระราชกฤษฎีกาว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ.2546 มาตรา 23', 'ความรู้และลักษณะการเป็นข้าราชการที่ดี', 'กพ ภาค ก', 0, 'กฎหมาย', '["พ.ร.ฎ.การบริหารกิจการบ้านเมืองที่ดี"]', '2566', 'รอบพิเศษ', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2566_รอบพิเศษ_047', 'นาง ก เป็นครูสอนวิทยาศาสตร์ของโรงเรียนแห่งหนึ่ง ก่อนทำการสอน นาง ก ไม่ได้ตรวจสอบสภาพการใข้งานของสายไฟที่เสื่อมชำรุด ทำให้ขณะทำการสอนเกิดไฟฟ้าช็อตนักเรียน กรณีดังกล่าวผู้ปกครองจะต้องฟ้องร้องใคร', '["ฟ้องครู/ศาลปกครอง", "ฟ้องครู/ศาลยุติธรรม", "ฟ้องโรงเรียน/ศาลยุติธรรม", "ฟ้องโรงเรียน/ศาลปกครอง"]', '3', 'ข้อสอบจริง ก.พ. ปี 2566 ชุด รอบพิเศษ

16. ตอบ 3) ฟ้องโรงเรียน/ศาลยุติธรรม
อ้างอิงตามพระราชบัญญัติความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539 มาตรา 5
เนื่องจากเป็นการละเมิดในการปฏิบัติหน้าที่ จึงต้องฟ้องหน่วยงานที่สังกัด และเป็นการปฏิบัติหน้าที่ตามปกติ ไม่มี
กฎ คำสั่ง หรือการใช้อำนาจตามกฎหมายเกี่ยวข้อง จึงฟ้องต่อศาลยุติธรรม', 'ความรู้และลักษณะการเป็นข้าราชการที่ดี', 'กพ ภาค ก', 0, 'กฎหมาย', '["พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง"]', '2566', 'รอบพิเศษ', 0);
